// Phase 2 — React project generation contract + parser.
//
// Sonnet emits a whole Vite/React/Tailwind PROJECT as a series of file blocks,
// each introduced by a line `===FILE: <relative/path>===`. This delimiter format
// avoids JSON-escaping code (quotes, backslashes, newlines) which is fragile for
// large multi-file output. The parser turns that text into { "<path>": "<src>" }
// ready to POST to the build-service.
//
// The build-service only allows writes to index.html / vite,tailwind,postcss
// configs / src/**, and the image deps are pre-baked, so the model MUST stay
// inside that shape and use ONLY the pinned packages.

export function parseGeneratedFiles(text) {
  const files = {};
  const s = String(text || "");
  // Split on the FILE markers (kept as capture groups → [pre, path, body, path, body, ...]).
  const parts = s.split(/^===FILE:\s*(.+?)\s*===[ \t]*$/gm);
  for (let i = 1; i < parts.length; i += 2) {
    const rawPath = (parts[i] || "").trim();
    let body = parts[i + 1] || "";
    // Trim one leading newline and trailing whitespace; strip an accidental
    // ```lang fence the model may wrap a block in.
    body = body.replace(/^\r?\n/, "").replace(/\s+$/, "");
    body = body.replace(/^```[a-zA-Z]*\r?\n/, "").replace(/\r?\n```$/, "");
    if (rawPath) files[rawPath] = body;
  }
  return files;
}

// The allowed dependency set (must match builder/package.json). The generator is
// told these are the ONLY importable packages.
export const REACT_DEPS = [
  "react", "react-dom", "react-router-dom", "lucide-react", "clsx", "tailwind-merge",
];

// Backend protocol — shared by build + revise. Only when the site genuinely needs
// to STORE data or LOG USERS IN does the model declare a schema and wire real
// forms to the platform's per-site backend (a Cloudflare D1 database provisioned
// automatically from the declaration). Informational sites emit nothing here.
export const BACKEND_RULES =
  "BACKEND (ONLY when the site must save data or sign users in — a form that persists, a login, a dashboard, a store; a purely informational site emits NOTHING here). " +
  "**CRITICAL — SCHEMA IS MANDATORY: if ANY file calls `${API}/auth/*` or `${API}/rows/<table>`, you MUST emit a file `===FILE: isibi.schema.json===` declaring every table used, or the live app 404s 'this site has no backend yet'.** Body: `{\"tables\":[{\"name\":\"<snake>\",\"access\":\"collect|display|user|feed|admin\",\"columns\":[{\"name\":\"<snake>\",\"type\":\"text|integer|real|boolean|json\",\"ref\"?:\"<table>\",\"required\"?:true,\"max\"?:N,\"min\"?:N,\"format\"?:\"email|url|number\",\"default\"?:<value>,\"enum\"?:[\"a\",\"b\"],\"pattern\"?:\"<regex>\"}]}]}`. Column rules are ENFORCED server-side on writes (a bad value → 400 with a message): `required`; `max`/`min` = length for text, value bounds for numbers; `default` = server default when omitted; `enum` = value must be one of the set; `pattern` = must match the regex; `format` = email/url/number; `immutable`:true LOCKS a field (settable on insert, but any later edit that includes it → 400 — use for an email, a created price, an order number); `default` also accepts computed tokens `\"@now\"` (current datetime), `\"@today\"` (date), `\"@uuid\"` (a random id) that the DB fills per-insert when you omit the field. CROSS-FIELD rules go in a TABLE-level `\"checks\":[[\"end_at\",\"gte\",\"start_at\"],[\"capacity\",\"gt\",\"reserved\"]]` (ops gt/gte/lt/lte/eq/ne, numeric when both are numbers else string/date) — enforced on writes when both fields are present (always on a full insert; on a partial update only if it carries both). Derived READ-ONLY columns go in a TABLE-level `\"computed\":{\"full_name\":[\"first_name\",\" \",\"last_name\"]}` — on read each token that names a column (incl. `id`/`created_at`) becomes that row's value, anything else is a literal, so you don't store a redundant `full_name`. To validate the inner shape of a `json` column, add a TABLE-level `\"jsonShapes\":{\"payload\":{\"type\":\"string\",\"count\":\"number\",\"tags\":\"array\"}}` — each listed inner field is REQUIRED and type-checked (string|number|boolean|array|object) on write, so a structured blob is validated, not just stored (a bad field → 400 naming it). For NUMERIC derived values use a TABLE-level `\"formulas\":{\"line_total\":[\"quantity\",\"*\",\"unit_price\"],\"net\":[\"subtotal\",\"-\",\"discount\"]}` — tokens are numeric columns or literal numbers joined by operators + - * / (correct precedence, * and / bind first); read-only per row, non-numeric operand or divide-by-zero → null; use it for money math (line totals, tax, margins) so the browser never recomputes it. MULTI-CURRENCY (store money in native currencies but report in ONE) — add a TABLE-level `\"currency\":{\"amount\":\"amount\",\"code\":\"currency\",\"base\":\"USD\",\"rates\":{\"EUR\":1.08,\"GBP\":1.27}}`: `amount` is the money column, `code` is the per-row ISO-currency column, `base` is what you report in, `rates` maps each other currency to base units per 1 unit (base is always 1). On READ each row gains `<amount>_base` (= amount × rate, or `as` to rename it), null when the row's currency has no rate. Crucially `stats` can `sum=/avg=` that base field — `?group=region&sum=amount_base` rolls a cross-currency pipeline up into ONE base-currency total in SQL (a EUR deal and a GBP deal add correctly), so dashboards never mix currencies. AUTO-NUMBERING (human-readable record numbers — invoice/order/quote/ticket/case IDs like INV-01000, LEAD-0042, PO/2001) — add a TABLE-level `\"sequence\":{\"field\":\"number\",\"prefix\":\"INV-\",\"pad\":5,\"start\":1000}` (`prefix`/`pad`/`start` optional — default no prefix, no padding, start 1). Every new row is stamped with the next number in sequence (atomic per-table counter → gap-free, no collisions even under load). The field is AUTHORITATIVE: it's platform-set, never app-writable, so a client can't spoof or reuse a number (a value sent for it is ignored), and it can't be changed by a later edit. It's queryable + sortable like any column (`?where=number:eq:INV-01001`, `?sort=-number`). Use it for any record that needs a stable customer-facing ID — don't try to compute one in the browser (that races). Declare these instead of validating only in the browser. Every table auto-gets `id`+`created_at`; `user`/`feed` also auto-get `owner_id` — NEVER declare those yourself. **ENCODE THE BRIEF'S RULES AS SCHEMA KEYS — the database is the only real enforcement (front-end checks race and are trivially bypassed), so a rule stated in words MUST become a schema constraint, not just a column:** 'one <X> per member' / 'per member per <Y>' / 'can only <do> once' → TABLE-level `oncePerUser:[\"<y>\"]` (use `[]` for once-per-member overall); 'rated 1-5' / 'score out of 10' / 'up to N chars' → column `min`/`max`; a record that BELONGS TO or is shown grouped under / filtered by a parent (comments on a post, RSVPs for an event, line-items of an order, a task in a project) → a `ref` column pointing at that parent table; a unique handle/username/slug/promo-code → `unique` (or `uniqueCI` for names/handles); a fixed choice set (status, category, role, priority) → `enum`; a must-fill field → `required`. If the brief says it, the schema carries it. STATE MACHINE / STAGE-GATING — when a status/stage field may only move along a set path (opportunity stage, order or ticket status, an approval flow), add a TABLE-level `\"transitions\":{\"<col>\":{\"<from>\":[\"<to>\",…]}}` (use `\"*\"` as a from-key to allow a move from ANY current value — its targets are ADDED to every state's own list, so `\"*\":[\"cancelled\"]` means 'cancellable from anywhere'). A PATCH that moves the column to a step not declared from its current value is refused with HTTP **409** `{code:'transition', from, to, allowed}` — catch it and show the valid next steps. The DB enforces the flow, so no invalid stage jump slips through; a PATCH that doesn't touch the column is unaffected. " +
  "ACCESS MODES (pick the right one): `collect` = visitors submit, only owner reads (contact/orders/RSVP); `display` = everyone reads, owner-managed content — starts EMPTY with no in-app editor, so hardcode a small fixed catalog instead; `user` = each login sees only their OWN private rows (dashboard, to-do, saved items); `feed` = everyone reads, a logged-in visitor posts + edits only their own (board, comments, reviews); `admin` = everyone reads, only an app admin writes — an in-app CMS WITH an add/edit UI (blog/catalog/events). Submit-AND-show = `feed` (not collect, which hides; not display, which blocks posting). " +
  "UNIQUENESS (stop duplicates race-free — 'one review per member per product', 'one RSVP per event per member', a unique slug/code): add a TABLE-level key next to `columns`. `\"oncePerUser\":[\"product_id\"]` on a `user`/`feed` table = at most ONE row per member per that value (owner_id is added automatically). `\"unique\":[\"code\"]` = globally unique; a composite like `\"unique\":[\"event_id\",\"seat\"]` = that pair unique. Enforced by the database, so a duplicate POST returns HTTP **409** `{error,code:'duplicate'}` — catch it and show a friendly 'you've already done this' (don't treat 409 as a crash). Prefer this over checking-then-inserting in JS (that races). Add `\"uniqueCI\":[\"handle\"]` for CASE-INSENSITIVE uniqueness (so 'Alice' collides with 'alice' — usernames, emails); same 409 `code:'duplicate'`. Add `\"maxRows\":100` to CAP a table's size (scoped PER-MEMBER on user/feed, global otherwise) — the row over the cap is refused with HTTP 409 `{code:'limit'}` (free-tier limits, 'max 100 todos per user'). Add `\"rateLimit\":5` to cap each member at N WRITES PER MINUTE to a table (anti-spam, 'max 5 posts/min') — over the cap → HTTP 429, catch it and show 'slow down'. To tune the WHOLE app's data-API throughput add a TOP-LEVEL `\"rateLimits\":{\"read\":300,\"write\":60}` (requests per IP per minute — the defaults shown) as a sibling of `tables`; raise it for a busy app or lower it to harden a quiet one (over the cap → 429). " +
  "**API BASE — MANDATORY, GET THIS EXACTLY RIGHT or the whole app 404s: the live site is served at `/s/<slug>/`, so you MUST derive the slug from the URL and put it in EVERY backend call. Define it ONCE: `const API = '/api/db/' + (location.pathname.split('/')[2] || '');` and route EVERY call through it — `${API}/auth/signup`, `${API}/auth/login`, `${API}/auth/me`, `${API}/rows/<table>`, `${API}/rows/<table>/<id>`, etc. NEVER hardcode `/api/db/auth/…` or `/api/db/rows/…` and NEVER write `` `/api/db${x}` `` — those drop the slug and every request fails. If you use a fetch helper/hook, build the URL as `` `${API}${path}` `` (API already contains the slug); do NOT bake a slugless `/api/db` into the helper and expect callers to add it.** All responses are JSON `{ok,...}`; guard every fetch in try/catch with friendly error/success states. " +
  "DATA: `GET ${API}/rows/<table>` (list) · `POST` (create — body of ONLY declared columns) · `GET/PATCH/DELETE ${API}/rows/<table>/<id>`. `user`/`feed`/`admin` writes send header `Authorization: Bearer <token>`. BATCH: `POST {rows:[…]}` (≤100) → `{inserted}`. FILE UPLOAD (an image or PDF — avatar, listing photo, resume): read the file as a base64 data URL and `POST ${API}/upload {name, data}` → `{url}`, a PERMANENT public link (images PNG/JPG/WebP/GIF + PDF, ≤6MB); then SAVE that `url` into a row (e.g. a listing's `photo` column) so it isn't orphaned. Needs the site to be live. SERVER-SIDE RESIZE/CONVERT (shrink big phone photos + convert format on the way in, so you store a bounded thumbnail not a 6MB original): add a `resize` to the upload body — `{name,data,resize:{max:1200}}` bounds the longest side to 1200px keeping aspect (downscale only), `{w,h}` sets exact/one-side dims, and `format:'jpeg'|'webp'|'png'` (+ optional `quality` 40–100 for jpeg) re-encodes it (webp = smallest, jpeg = photos, png = keeps alpha). The returned `{url,type,size}` reflect the transformed file. Only PNG/JPG/WebP are transformed (GIF/PDF pass through). Use it for avatars/thumbnails to keep storage small. UPSERT (one-row-per-key: settings, a like toggle): `POST ${API}/rows/<t>?upsert=<col>` updates the row matching `<col>` (scoped to the user on user/feed tables) else inserts → `{ok,created}`. BULK (mark-all-read, delete-selected, archive-done): `PATCH ${API}/rows/<t>?where=…` updates every matching row with the body → `{updated:N}`; `DELETE ${API}/rows/<t>?where=…` deletes every matching row → `{deleted:N}`. A `where`/`q`/`tag` FILTER is REQUIRED (no unfiltered mass changes), it's capped at 1000 rows/call, and scoped like single writes (feed/user only YOUR rows, admin any). To delete a specific SET, use `?where=id:in:1,2,3`. " +
  "QUERY (always filter/paginate on the SERVER, never fetch-all-and-filter): list params `where=<col>:<op>:<val>` (repeatable, AND-ed; op `eq|ne|lt|lte|gt|gte|contains|startswith|endswith|in|nin|between|isnull|notnull` — `in`/`nin` take a comma list e.g. `where=status:in:draft,live`; `between` takes two bounds `where=price:between:20:100` (inclusive, for price bands / date windows); `isnull`/`notnull` ignore the value), `q=<text>` (multi-word, relevance-ranked — for a big text corpus, declare a TABLE-level `\"fts\":true` (or `[\"title\",\"body\"]`) and search with `?fts=<query>` instead: a real FULL-TEXT index (FTS5, bm25-ranked, prefix + AND terms), far faster and better-ranked than `q=`'s LIKE scan on large tables; to weight fields so title matches outrank body matches, add a TABLE-level `\"searchWeights\":{\"title\":5,\"body\":1}` — `q` then ranks by weighted matches in those columns). SORT: one column `sort=<col>&order=asc|desc`, OR multiple comma-separated with a per-column direction prefix `sort=-price,name` (`-`=desc, `+`/none uses `order`), OR `sort=random` for a shuffled/discover/featured surface (pair with a small `limit` to pick N random rows). PAGINATE two ways: `limit`(≤200)+`offset` (jump to any page; response carries `{total}`), OR keyset for endless 'load more' — pass `after=<lastRowId>` to get the next older page (stable + fast on big lists; use the id of the last row you got as the next `after`). STATS / REPORTS: `GET ${API}/rows/<t>/stats?sum=<col>&avg=&min=&max=&group=<col>` Add `&distinct=<col>` for a UNIQUE count (`distinct:{<col>:n}` — 'how many distinct customers'). → `{count, sum:{…}, groups:[{value,count,sum}]}` (respects where/q/tag; user tables scope to the caller). `group` accepts MULTIPLE comma-separated columns for a matrix/pivot report (up to 4 dimensions) — e.g. `?group=stage,owner_id&sum=amount&avg=amount` returns `{groupBy:[…], groups:[{stage, owner_id, count, sum:{amount}, avg:{amount}}]}` (one row per combination), so you get 'pipeline by stage AND by rep' in ONE request. CROSS-TABLE grouping — group by a column on a REFERENCED parent with a `<fkcol>.<parentcol>` token: e.g. on opportunities (each has `account_id` ref accounts) `?group=account_id.industry&sum=amount` returns pipeline value grouped by each opportunity's ACCOUNT's industry — a join you'd otherwise do client-side, in one request (`{group:'account_id.industry', groups:[{value:'software', count, sum:{amount}}]}`). The `where=`/owner-scope filter still applies to the child table first. TIME-SERIES grouping — group by a TRUNCATED timestamp with a `<datecol>:<granularity>` token (granularity year|month|week|day|hour): `?group=closed_at:month&sum=amount` returns one bucket per month ordered CHRONOLOGICALLY (`{group:'closed_at:month', groups:[{value:'2026-01', count, sum:{amount}}]}`) — a revenue-per-month / leads-per-week trend line in one request, no client-side date bucketing. Works on `created_at`/`updated_at` or any declared ISO-date column; combine with `where=` (e.g. won deals only). Add `&fill=1` to ZERO-FILL empty periods (a month/day/hour/year with no rows still appears with `count:0`) so a trend line is continuous with no gaps — filled buckets carry the same shape (0/null aggregates); works for year/month/day/hour (not week), capped at 2000 buckets. GROUPED-REPORT CONTROLS (apply to ANY grouped stats — plain, matrix, cross-table, or time): `groupSort=<count|sum:col|avg:col|min:col|max:col|value>` + `groupOrder=asc|desc` sorts the groups by an aggregate (default `count` desc) — a revenue leaderboard is `?group=rep&sum=amount&groupSort=sum:amount&groupOrder=desc`; `groupLimit=<n>` caps to the top-N (so add `&groupLimit=10` for 'top 10 accounts'); `having=<agg>:<op>:<n>` (repeatable, AND-ed; op gt/gte/lt/lte/eq/ne; agg = `count` or `<sum|avg|…>:col`) filters the GROUPS themselves — `?group=rep&sum=amount&having=sum:amount:gte:50000` returns only reps whose pipeline clears 50k (quota reports, big-account filters). HAVING needs a `group`; it's ignored on an ungrouped total. EXPRESSION AGGREGATES (aggregate an arithmetic expression, not just a column — a WEIGHTED pipeline forecast, a discounted total): `sum=<alias>:<expr>` where `<expr>` is `+ - * /` and parens over declared numeric columns and number literals — e.g. `?group=rep&sum=weighted:amount*probability/100` returns each rep's weighted pipeline `{sum:{weighted: …}}` summed IN SQL (a formula field is read-time and can't be SUMmed). Works for `sum/avg/min/max`, in every grouped or ungrouped stats path, and you can `groupSort=sum:<alias>` / `having=sum:<alias>:gt:N` by it. Note integer columns use integer math, so multiply BEFORE dividing (`amount*probability/100`, not `amount*(probability/100)`); URL-encode a literal `+` as `%2B`. Combine with `where=` to scope a report (e.g. this-quarter). Use this for dashboards/KPIs instead of pulling rows and aggregating in the browser.FACETS (filter sidebars — 'Red (12) · Blue (4)', category/brand/size counts): `GET ${API}/rows/<t>/facets?fields=<colA>,<colB>` → `{facets:{colA:[{value,count},…], colB:[…]}}` (each column's distinct values + how many rows have each, top 100 by count). It respects the CURRENTLY-applied `where`/`q`/`tag` too, so as the user ticks filters the remaining counts narrow (drill-down). Use it to build a checkbox filter panel with live counts in ONE request instead of counting client-side. HISTOGRAM (distribution of a NUMERIC column into ranges — price bands, score/age spread, 'orders in each $10 band'): `GET ${API}/rows/<t>/histogram?col=<numcol>&buckets=N` buckets the column into N equal-width ranges and counts rows per range → `{col, min, max, width, total, buckets:[{lo,hi,count}, …]}`. Bounds auto-compute from the data, or pin them with `&min=&max=` (values outside pinned bounds clamp into the edge buckets; `buckets` default 10, max 100). Respects the same where/q/tag/trash filters + read visibility as stats (a `user` table counts only the caller's own rows). Use it for a distribution bar chart; use `group=` stats when the column already holds discrete categories. COLUMN PROFILE / DESCRIBE ('what's in this table' — a data-quality / admin overview in ONE call): `GET ${API}/rows/<t>/profile` → `{total, columns:[{name, type, non_null, nulls, distinct, min, max, avg?, sum?}]}` — per-column completeness (nulls), cardinality (distinct), range (min/max), and for numeric columns avg+sum, computed over the visible rows in a single query. Same read visibility + trash filters as stats (a `user` table profiles only the caller's own rows; `collect` has none). Use it to render a table-overview / data-health panel or spot empty/low-cardinality columns, instead of firing a stats call per column. DRY-RUN VALIDATION (check a row against the table's rules WITHOUT saving — live 'is this valid?' feedback on a form, a check-before-submit step): `POST ${API}/rows/<t>/validate {<fields>}` → `{valid:true}` or `{valid:false, error:'<message>'}`, running the SAME server-side checks a real create would (required, enum, min/max, pattern, format, immutable, cross-field `checks`, `jsonShapes`) but touching nothing. Default checks a CREATE; add `?partial=1` to check an EDIT (absent required fields are fine, immutables still rejected). It does NOT check uniqueness/refs — use `/duplicates` for that. No login needed (no data touched). Use it to validate as the user types instead of duplicating every rule in the browser. DUPLICATE CHECK ('does this contact/lead already exist?' before a create): `GET ${API}/rows/<t>/duplicates?email=<v>[&phone=<v>]` → `{matches:[…], count, on:[…]}` — existing rows matching ANY of the supplied declared columns (case-insensitive, trimmed), so a create form can warn 'a contact with this email already exists' and offer to open it instead of making a dupe. Add `&exclude=<id>` when checking during an EDIT so the row doesn't flag itself. Same read visibility as the table (a `user` table checks only the caller's own/team rows; public-read tables check all; `collect` has none). Pair with `/merge` to fold a found duplicate together, or use column-level `uniqueCI` when you'd rather HARD-block the duplicate at write time. GLOBAL SEARCH (one search bar across the WHOLE app — type a name, get matching contacts AND deals AND tickets): `GET ${API}/search?q=<text>[&tables=a,b][&per=N]` runs the same free-text `q` match your list reads use, over EVERY readable table at once, and returns `{results:[{table, rows}], count}` grouped by table (per-table cap `per`, default 5). Per-table visibility is enforced exactly like a list read — public-read tables (display/feed/admin) search all rows, a `user` table only the signed-in caller's own (skipped when signed out), `collect` never; trashed rows are excluded and field-level security is applied. Send the caller's Bearer token so their private records are included. Use `tables=` to scope (e.g. just contacts+companies). This is the backend for a command-palette / global search box; for one table use the list read's `?q=` instead.NEARBY / GEO: on a table with coordinate columns declare `\"geo\":{\"lat\":\"latitude\",\"lng\":\"longitude\"}` (or just name them `lat`/`lng`), then `GET ${API}/rows/<t>/near?lat=<>&lng=<>&radius=<km>[&limit=<>]` returns rows within the radius, NEAREST FIRST, each with `row._distance_km` — for 'stores near me', map results, local listings. SLA / DEADLINES (response/resolution timers on tickets, cases, leads — 'respond within 4h', 'resolve within 2 days'): add a TABLE-level `\"sla\":{\"start\":\"opened_at\",\"mins\":\"4h\",\"done\":{\"field\":\"status\",\"values\":[\"resolved\",\"closed\"]}}` — the clock runs from the `start` date column (default `created_at`) for `mins` (a number of minutes or a duration like `30m`/`4h`/`2d`/`1w`); when the row's `done` status column holds a stop value the clock is MET. Every read then carries a `row._sla = {due_at, remaining_mins, overdue, done}` (no config to render an 'overdue' badge, sort by urgency, or color a countdown). The OVERDUE QUEUE is `GET ${API}/rows/<t>/overdue[?where=&limit=&offset=]` → rows past their deadline and not done, MOST-OVERDUE FIRST, each with `_sla`, computed in SQL so it filters/paginates server-side (respects the table's read visibility + your `where=`). Build a 'breaching SLA' worklist from it. ESCALATION — add an `\"escalate\"` block to the sla config: `\"sla\":{…,\"escalate\":{\"to\":\"<member id or email>\",\"field\":\"priority\",\"value\":\"urgent\"}}` — then `POST ${API}/rows/<t>/overdue/escalate` (ADMIN) applies that action to every overdue row not yet escalated (reassign `owner_id` to `to` and/or set `field`=`value`), returning `{escalated:<count>}`. It's IDEMPOTENT (rows already at the target are skipped, so re-running is safe) and does NOT resolve the rows (they stay overdue until their status reaches a `done` value). There's no built-in timer — call this endpoint from a scheduled function or an external cron to fire escalation automatically, or wire an 'Escalate overdue' admin button to it. `to` needs an owner column (a `user`/`feed` table); a field-only escalate works on any writable table." +
  "TAGS / LABELS (categorize any row and filter by it — post topics, product categories, task labels): `POST ${API}/rows/<t>/<id>/tags {tag}` adds a tag (same write scope as the row: feed/user your own row, admin any), `DELETE ${API}/rows/<t>/<id>/tags/<tag>` removes it, `GET ${API}/rows/<t>/<id>/tags` lists them. To SHOW tags on a feed add `?tags=1` and each row comes back with `row.tags` (array). To FILTER a list to one tag add `?tag=<name>` to the list read. Tags are short (letters/numbers/-/_), deduped per row. " +
  "RELATIONS: declare a fk column with `ref` (`{\"name\":\"post_id\",\"ref\":\"posts\"}`). `?expand=<fk>` attaches the parent as `row. A dotted token `expand=customer_id.company_id` DEEP-expands up the chain (order → customer → company) in one request.<fk minus _id>`; `?children=<child_table>` attaches an array of children under that name. Both batched (no N+1); can ONLY join a PUBLIC-READ table (display/feed/admin) — never leaks user/collect rows. Deleting a parent row AUTO-deletes its children (cascade) — you don't clean them up yourself. Add `\"enforceRefs\":true` to a TABLE to REJECT a write whose fk points at a non-existent parent (HTTP 400 `{code:'ref'}` — no orphan rows); a NULL fk stays allowed (optional link). Control what happens to children when the parent is deleted via a column-level `\"onDelete\"` on the fk: `\"cascade\"` (default — children deleted with the parent), `\"setNull\"` (children KEPT, their fk nulled — e.g. keep line items when a category is removed), or `\"restrict\"` (REFUSE the parent delete with 409 `{code:'restrict'}` while any child still points at it). THREADED / NESTED (replies-to-replies, a category tree, an org chart — a table that references ITSELF): give it a column with `ref` back to its OWN name (`{\"name\":\"parent_id\",\"ref\":\"comments\"}`), then `GET ${API}/rows/<t>/tree` returns the rows NESTED — each carries a `replies` array of its children (recursive); `?root=<id>` returns one subtree; honors `?authors=1`/`?reactions=1`. MANY-TO-MANY LINKS (a bidirectional relationship between rows WITHOUT declaring a join table — tags↔posts, users↔projects, 'related items'): `POST ${API}/link {a,b}` (Bearer) links two rows where a/b are `<table>:<id>` (e.g. `post:1`, `tag:5`); `DELETE ${API}/link {a,b}` unlinks; `GET ${API}/links/<table>:<id>[?to=<table>]` → the rows linked to it `[{target,table,id}]`, queryable from EITHER side. Deduped + undirected. (If the link needs its OWN data — a role, a quantity — use a real join table with two `ref` columns instead.) " +
  "EDIT TIMESTAMPS: add `\"timestamps\":true` to a TABLE → every row auto-gets `updated_at` (set on create, bumped on every edit, returned on reads) with NO extra code — sort by it for 'recently updated' or show an 'edited' state. READ SHAPING (both optional, on any list/get): `?fields=a,b` returns ONLY those columns (plus `id`, always) to shrink big lists; `?count=<child_table>` attaches `row._counts.<child>` = how many children point at each row, so a feed shows '12 comments' WITHOUT fetching them (peer of `?children`, public-read children only). `?rollup=<child>:<agg>:<col>` (agg sum/avg/min/max/count; comma-separate several) rolls a child column UP onto each parent as `row._rollups.<child>.<agg>.<col>` — an order total (`line_items:sum:amount`), an average rating (`reviews:avg:rating`), a highest bid — again without fetching the children. " +
  "SOFT DELETE / TRASH (a recycle bin — 'archive', 'move to trash', 'undo delete', so nothing is lost by accident): add `\"trash\":true` to the TABLE (sibling of columns). Then `DELETE ${API}/rows/<t>/<id>` HIDES the row (marks it trashed) instead of erasing it, and every read EXCLUDES trashed rows automatically. To build a trash/archive view: list with `?trashed=1` (only trashed) — restore one with `POST ${API}/rows/<t>/<id>/restore`. `?withTrashed=1` lists live+trashed together. To delete for real (empty-trash / permanent), add `?hard=1` to the DELETE. Same write scope as normal (feed/user own row, admin any). Use this whenever the user should be able to recover a deletion. " +
  "ARCHIVE (Gmail-style — file a row away without deleting it, SEPARATE from trash): add `\"archivable\":true` to the TABLE → `POST ${API}/rows/<t>/<id>/archive` hides it from normal lists and `POST ${API}/rows/<t>/<id>/unarchive` brings it back. Reads exclude archived by default; `?archived=1` lists the archive view, `?withArchived=1` lists everything. Same write scope as the table. Use for 'archive project', 'done' items you keep, an inbox archive. " +
  "ORDERED LISTS / DRAG-TO-REORDER (a hand-arranged list — todos, a playlist, kanban cards, a gallery): add `\"ordered\":true` to the TABLE → each row auto-gets a `position` (appended to the END on insert, scoped per-member on user/feed), and you reorder with `POST ${API}/rows/<t>/<id>/move` sending `{after:<id>}` or `{before:<id>}` (drop it beside that row) or `{to:<number>}` (absolute). List with `?sort=position&order=asc`. Positions are fractional so one move never renumbers the rest. Same write scope as the table (feed/user your own rows, admin any). ASSIGN / LEAD ROUTING (hand a record to another member — assign a lead to a rep, reassign a case): `POST ${API}/rows/<t>/<id>/assign {user:<memberId or email>}` on a `user`/`feed` table sets that row's owner to the named member. Allowed for an ADMIN (or, on a `teamRead` table, the current owner's MANAGER). Combine with `teamRead` so the new owner's manager still sees it; it also fires any `on:{update}` automation. MERGE DUPLICATES (dedupe two records into one — merge duplicate accounts/contacts): `POST ${API}/rows/<t>/<id>/merge {from:<otherId>, fillBlanks?:true}` (ADMIN) folds the `from` record INTO this one — every child row that references `from` (via a `ref`) is repointed to this id, then `from` is deleted. `fillBlanks:true` first copies the loser's non-empty values into this record's still-empty fields (keep the fuller record). The loser's ACTIVITY comes along too — its notes, attachments, approvals, and tags are moved onto the survivor (duplicate tags/reactions deduped), so a merge never loses history. Returns `{into, from, repointed:{table:count}}`. DUPLICATE a record — `POST ${API}/rows/<t>/<id>/clone` (optionally `{overrides:{…}}`) copies a row into a NEW one (auto id/slug/number/timestamps regenerate; the caller becomes owner on user/feed tables) — for a 'Duplicate' button on an invoice/project/template. Override any field (e.g. a UNIQUE code, or a new title); a UNIQUE clash you didn't override comes back 409. " +
  "EXPIRING ROWS / TTL (a row that should disappear after a time — a flash-sale price, a 24h story, a one-time invite, a temp share link): add `\"expires\":true` to the TABLE → the row auto-gets an `expires_at` column that YOU set to a datetime/ISO string when creating it, and every read then HIDES rows whose `expires_at` has passed (leave it NULL = never expires). `?expired=1` lists only the expired ones, `?withExpired=1` lists all. Renew by PATCHing `expires_at` to a later time. Hidden, not deleted (sweep them with a scheduled function if you want them physically gone). " +
  "SCHEDULED PUBLISH / DRAFTS (a post that auto-goes-live at a set time, or a draft hidden until ready — the inverse of expiring rows): add `\"publishable\":true` to the TABLE → the row auto-gets a `publish_at` column; leave it NULL to publish immediately, or set it to a FUTURE datetime and the row stays HIDDEN from reads until then (goes live automatically, no cron needed). `?scheduled=1` lists the not-yet-published (a 'Scheduled'/drafts admin view), `?withScheduled=1` lists everything. Publish now by PATCHing `publish_at` to null or a past time. " +
  "FEATURED / PINNED + DEFAULT ORDER: add `\"pinnable\":true` to a TABLE → each row gets a `pinned` flag (0/1) that YOU set, and pinned rows ALWAYS list first (sticky posts, featured products, announcements) with the normal order applying within each group; `pinned` is queryable/sortable like any column (`where=pinned:eq:1`). Add `\"defaultSort\":\"-created_at\"` to a TABLE (same prefix convention as `?sort`: `-`=desc, `+`=asc, e.g. `\"+title\"`) so its list has a built-in order when a request sends no `sort` of its own — the app can still override per query. " +
  "REALTIME (chat/live feed): `GET ${API}/rows/<t>/changes?since=<cursor>` returns only newer rows (ascending) + a fresh `{cursor}`+`{count}`; add `&wait=1` to long-poll up to ~20s (returns the instant a row lands). For a full CHANGE LOG (updates and deletes too, not just new rows) on an `audit:true` table, `GET ${API}/rows/<t>/events?since=<cursor>` returns the insert/update/delete stream (admin) — use it to sync an external system. Seed the cursor from the newest id of your initial list, then loop. Appends only (re-list to catch edits). OFFLINE SYNC (keep a local copy current — pull edits AND deletes since last time, not just new rows): add `\"sync\":true` to the TABLE, then `GET ${API}/rows/<t>/changes?sync=<lastCursor>` returns `{updated:[rows created OR edited since], deleted:[ids removed since], at:<newCursor>}` — apply the updates, drop the deleted ids from your local copy, save `at` for next time (first call: `?sync=` empty = full pull). " +
  "ATOMIC INCREMENT (change a NUMBER on ONE row race-free — decrement stock on a purchase, +1 a score/quantity/view on a specific record): `POST ${API}/rows/<t>/<id>/incr {col, by}` adds `by` (default 1, negative to subtract) to that numeric column and returns `{value}` (the new number); pass `{col,by,min:0}` to floor it (stock never goes below 0). Write scope matches the table (feed/user → your own row, needs the Bearer; admin → any row). Use this instead of read-then-write (which races). For a TALLY not tied to a row (page views, anonymous likes) use a counter instead. " +
  "OPTIMISTIC LOCKING / NO LOST UPDATES (when two people can edit the SAME row — a shared doc, a collaborative board, an admin CMS with several editors — stop the second save from silently overwriting the first): add `\"version\":true` to the TABLE (sibling of columns). Every row then carries a `_version` number that auto-increments on each edit and is returned on reads (`row._version`). When you PATCH, send the version you loaded: `PATCH ${API}/rows/<t>/<id>?ifVersion=<n>` (or header `If-Match: <n>`). If someone else edited it since, the write is REFUSED with HTTP **409** `{code:'conflict', version:<current>}` — catch it, tell the user 'this changed, reload', and refetch. A successful PATCH returns `{ok:true, version:<new>}` so you can keep editing. Omit `ifVersion` to force-write (last-writer-wins). Use this on any row multiple members can edit. " +
  "ROW HISTORY / UNDO (keep a version history of a row and let its owner restore a past version — docs, listings, a profile, anything edited over time): add `\"history\":true` to the TABLE → every edit snapshots the previous values automatically; the row's OWNER (or an admin) reads `GET ${API}/rows/<t>/<id>/history` → `[{id, snapshot, at}]` newest-first, and restores one with `POST ${API}/rows/<t>/<id>/revert/<historyId>` (the revert is itself recorded, so it too is undoable); and `GET ${API}/rows/<t>/<id>/diff[/<histId>]` returns what CHANGED between a snapshot (the latest by default, or `/<histId>` or `?rev=`) and the current row — `{changed, changes:{col:{from,to}}}` — for a 'what changed' revision view. " +
  "PER-ROW SHARING / ACL (let a member share ONE of their private records with specific other members — a shared doc/board/trip/list, Google-Docs style; ONLY on a `user`-access table): the row's OWNER manages access — `POST ${API}/rows/<t>/<id>/share {user:'<email or member id>', perm:'view'|'edit'}` grants (re-POST to change the level), `DELETE ${API}/rows/<t>/<id>/share/<memberId>` revokes, `GET ${API}/rows/<t>/<id>/share` lists who it's shared with (owner only, Bearer). The RECIPIENT then: sees it via `GET ${API}/rows/<t>/<id>` (their normal reads still only show their OWN rows — to list everything shared WITH them add `?shared=1` to the list read), and if granted `edit` may `PATCH` it (a `view` share is read-only). DELETE stays owner-only (a collaborator can edit content but never delete someone else's row). Use this for real collaboration instead of copying a row per user. " +
  "CUSTOM ROLES / RBAC (roles beyond just admin/user — moderator, editor, staff — that can write to an `admin` table): on an `admin`-access table add a table-level `\"writeRoles\":[\"editor\",\"admin\"]` (sibling of columns) → members whose role is any of those may write (create/edit/delete); everyone still READS. The built-in `admin` role can ALWAYS write (superuser), so you needn't list it. Members default to role `user`; the OWNER assigns roles from their dashboard (there's no in-app self-serve role change — that'd be a privilege-escalation hole). So use `writeRoles` for 'editors can post articles, everyone reads' style gates; use `user`/`feed` when each member only touches their OWN rows. FIELD-LEVEL SECURITY (hide sensitive columns from some roles — salary, cost, margin, SSN): add a TABLE-level `\"fieldRoles\":{\"amount\":[\"admin\",\"manager\"],\"cost\":[\"admin\"]}` mapping a column to the roles allowed to READ it. On reads the column is STRIPPED for anyone whose role isn.t listed (signed-out visitors count as role `public`); an `admin` always sees every field. So reps see the deal but not its margin. FIELD MASKING (partial-reveal instead of fully hiding — show `••••4242` of a card, the last 4 of a phone/SSN): a TABLE-level `\"mask\":{\"number\":{\"roles\":[\"admin\"],\"keep\":4},\"cvv\":{\"roles\":[\"admin\"],\"keep\":0}}` — readers whose role isn't listed see the value with only its last `keep` chars, the rest replaced by `•` (an admin always sees it whole). Use `mask` when the shape should stay visible (a masked card still reads as a card); use `fieldRoles` when the field should vanish entirely.Combine with `writeRoles` to also gate who can edit the table. TEAM / MANAGER VISIBILITY (a manager sees their reports. records — CRM roll-up, org-scoped dashboards): add `\"teamRead\":true` to a `user` table. Members are arranged into a hierarchy by the OWNER (member management sets each member.s manager); then on READS (list/single/stats/facets) a member also sees rows owned by their whole downline (recursive), not just their own. WRITES stay own-row-only (a manager views but doesn.t edit a report.s row). A member with no reports is unaffected. APPROVAL WORKFLOW (sign-off before a record is final — expense/discount/big-deal approval, content review): add a TABLE-level `\"approval\":{\"approvers\":[\"manager\",\"admin\"],\"status\":\"approval_status\"}` (`status` optional, defaults to `approval_status`). It platform-adds a `status` column that is READ-ONLY to the app (queryable/sortable, but NEVER settable via a normal write — so an owner can.t self-approve by editing the row). Drive it with these endpoints (Bearer): `POST ${API}/rows/<t>/<id>/submit {note?}` (a writer of the row — its owner on user/feed, or an admin/writeRole on an admin table) sets status→`pending`; `POST ${API}/rows/<t>/<id>/approve {note?}` and `POST ${API}/rows/<t>/<id>/reject {note?}` (a member whose role is in `approvers`, or admin) set it to `approved`/`rejected`; `GET ${API}/rows/<t>/<id>/approvals` returns the decision LOG (who submitted/approved/rejected, when, note) + current status. The pending QUEUE is just a normal list filter: `?where=approval_status:eq:pending` (approvers see items to action; pairs with `teamRead` so a manager sees their team.s). approve/reject fire `on:{update}` functions. Use this instead of a plain enum column when a decision must be gated to certain roles AND audited. ROUND-ROBIN ASSIGNMENT / LEAD ROUTING (auto-distribute new records across a team — incoming leads/cases/tickets spread evenly over the reps): on a `user` or `feed` table add `\"roundRobin\":{\"among\":[\"rep\"]}` (the roles that form the pool). Each new row's `owner_id` is auto-assigned to the NEXT member of that pool in rotation (stable order, atomic counter → even distribution, no double-assign), regardless of who created it — so an admin or a public intake can file leads and they fan out to the sales team. Blocked members are skipped; an empty pool falls back to the creator (a record is never left unowned). The create response returns the chosen `owner_id`. Pair with `teamRead` so a manager sees the whole team's assigned records, and with `/assign` for manual re-routing. TERRITORY / FIELD-BASED ROUTING (send a new record to a SPECIFIC owner by one of its field values — leads from a region, deals of a product line, tickets of a tier): on a `user`/`feed` table add `\"assignBy\":{\"field\":\"region\",\"map\":{\"west\":\"<member id or email>\",\"east\":\"…\"},\"default\":\"<id|email>\"}`. On insert the row's `field` value (case-insensitive) is looked up in `map` → that member becomes `owner_id`; an unmapped value uses `default` (omit it to fall through). Territory routing takes PRECEDENCE over `roundRobin` on the same table, so you can pin known segments to named reps and let round-robin spread everything else — declare both together. The member must exist (id or email); if none resolves it falls back to round-robin, then the creator." +
  "AUTO SLUGS / PRETTY URLS (a clean url-safe key per row for `/blog/my-first-post` or `/p/blue-widget` instead of `?id=42`): add a TABLE-level `\"slug\":\"<sourceColumn>\"` (sibling of columns, e.g. `\"slug\":\"title\"`). On insert the platform fills a `slug` column from that source — lowercased, spaces/punctuation → dashes, diacritics folded (\"My First Post!\" → `my-first-post`) — and GUARANTEES it's unique (appends `-2`, `-3`, … on collision), so you can route by it safely. Read one row by slug with `GET ${API}/rows/<t>?where=slug:eq:<theSlug>` (take `rows[0]`); the `slug` field is returned on every read. Use it in links (`/post/${row.slug}`). You may also POST your own `slug` (it's normalized + still policed for uniqueness → 409 on a dup). Don't declare a `slug` column yourself — declaring `\"slug\":\"title\"` on the table is enough. " +
  "JSON / NESTED COLUMNS (store a whole object or list in ONE column — an order's line-items array, a settings object, tags/options, flexible metadata that doesn't deserve its own table): declare the column `\"type\":\"json\"` (aliases `array`/`object`). Then just POST/PATCH the real value — send `{items:[{sku,qty},…]}` or `{prefs:{theme:'dark'}}` as an actual array/object (NOT a JSON string) and read it back as a parsed array/object (NOT a string). The platform stringifies on write and parses on read for you, everywhere (single row, list, batch, realtime). Use this for genuinely nested/variable-shape data; use a related `ref` table instead when you need to QUERY or sort by the inner rows (you can't `where=` into a json column). " +
  "COUNTERS (likes · view counts · reactions · poll tallies — anything that just tallies up, where a race-free atomic count matters and a full row per event is overkill): `POST ${API}/count/<name>` increments a named counter and returns `{value}` (the NEW total); add `?by=N` to add N (negative to subtract, e.g. undo a like; floored at 0). `GET ${API}/count/<name>` → `{value}`; `GET ${API}/count` → `{counters:{name:value,…}}` for a whole dashboard. PUBLIC + atomic (no login, no races) — use a per-thing name like `like:post:${id}`, `views:home`, `poll:color:blue`. Use this for tallies; use a `feed` table only when you need one ROW per event (who/when/text). For an ANONYMOUS view/like tally a counter is enough; if it must be ONE-per-USER (a like/upvote/RSVP that a member can toggle), use REACTIONS instead (below) — it dedupes for you. " +
  "REACTIONS (one-per-user likes · upvotes/downvotes · RSVPs · emoji — a signed-in member toggles it, and you need the count AND whether THIS member reacted): `POST ${API}/react/<target> {type}` (Bearer; `type` default `'like'`) TOGGLES the caller's reaction and returns `{reacted, count}` (pass `{type,on:true|false}` to force on/off). `GET ${API}/react/<target>` → `{counts:{type:n,…}, mine:[types you reacted with]}` (send the Bearer to get `mine`; anon gets counts only). **`<target>` MUST be `<tableName>:${id}` — the exact table name plus the row id (e.g. `posts:${id}`, `comments:${id}`) — so your manual react calls line up with the `?reactions=1` feed shortcut below; a mismatched target (e.g. `post:` vs the `posts` table) makes the button and the feed count disagree.** Dedup is enforced server-side (one per member+target+type) — you do NOT need a side table. **FEED SHORTCUT: add `?reactions=1` to a list read and every row comes back with `row.reactions = {counts, mine}` for target `<table>:<id>` (batched, and `mine` reflects the logged-in caller)** — so a list of posts renders like/upvote buttons with counts and the user's own state in ONE request. Combine with `?authors=1` freely. " +
  "POLLS (one vote per member, changeable — 'best logo', a survey, a with-options RSVP): `POST ${API}/poll/<pollId>/<option>` (Bearer) casts or CHANGES the caller's vote → `{counts:{option:n}, total, mine}`; `GET ${API}/poll/<pollId>` → the same tally (Bearer → `mine` = your chosen option); `DELETE ${API}/poll/<pollId>` (Bearer) withdraws it. pollId + option are your own strings (e.g. poll `logo-2026`, options `red`/`blue`). One-vote-per-member is enforced server-side (re-voting moves it), so you don't hand-roll it. " +
  "MENTIONS (@-mention members and notify them): when a member posts text containing @handles, resolve those handles to user ids client-side (you have the member list via profiles), then `POST ${API}/mention {target:'<table>:<id>', users:[<ids>], text?}` (Bearer) drops a `mention` notification into each mentioned member's inbox (with `link` = target). Capped ≤10 recipients/call, rate-limited, and deduped per target+member within an hour (so it can't spam). Pairs with the notifications inbox. " +
  "NOTIFICATIONS (a per-member inbox + unread badge — 'someone commented on your post', 'your order shipped'): a signed-in member reads THEIR OWN inbox with `GET ${API}/notifications` (Bearer) → `{rows:[{id,type,text,link,read,created_at}], unread}` (add `?unread=1` for only-unread); mark one read `POST ${API}/notifications/<id>/read`, or all `POST ${API}/notifications/read-all`. Poll `unread` for the badge. Notifications are CREATED server-side only — a `{\"do\":\"notify\",…}` step in a function (usually an on-insert TRIGGER: new comment → notify the post's owner_id), never by the browser — so members can't spam each other. " +
  "AUTH (for user/feed/admin): `POST ${API}/auth/signup` · `/auth/login` `{email,password}` → `{token,user}` (store token in localStorage); `GET ${API}/auth/me` with the Bearer header verifies the session. ROLES: `user.role` — first signup becomes `'admin'`, rest `'user'`; gate admin UI on `user.role==='admin'` (server also enforces: non-admin write to an admin table → 403). FORGOT PASSWORD: a form POSTing `${API}/auth/reset-request {email}` — always resolves ok, show ONE neutral message ('if that email has an account…'), never reveal existence; the platform sends the email + hosts the reset page (you build only the form). EMAIL VERIFY: automatic on signup; `user.verified` (0/1) is available if you want to gate on it, with a 'Resend' → `${API}/auth/verify-request`; most apps ignore it. To REQUIRE a confirmed email before a member may WRITE to a given table, add `\"requireVerified\":true` to that TABLE — unverified writes then get 403 `{code:'unverified'}` (reads still work), so gate sensitive posting on it. INVITE-ONLY: if the owner turned on invite-only signup, `POST ${API}/auth/signup` returns `{ok:false, need:'invite'}` (403) unless the body includes a valid `invite` code — so ALWAYS include an optional 'Invite code' field on the sign-up form and pass it as `invite`; on a `need:'invite'` error, reveal/hint the invite field. The owner turns this on and mints codes from their dashboard; you don't manage codes in the app. ACCOUNT SETTINGS (a signed-in member manages their OWN account): `POST ${API}/auth/password {current_password, password}` changes the password (re-checks the current one, returns a fresh `token` — store it); `POST ${API}/auth/email {password, email}` changes the email (returns a fresh token); `DELETE ${API}/auth/account {password}` permanently deletes the account plus that member's own rows AND their personal side-data (direct messages, block edges, login history, presence, consents, saved views, and notes they authored) — a real right-to-be-forgotten erase. Each re-verifies the current password (a stolen token alone can't). `POST ${API}/auth/logout-all` (Bearer) logs the account out of OTHER devices and returns a FRESH token for THIS one (store it) — every device's next `/auth/me` check then fails and forces re-login. Build an 'Account settings' page from these when the app has logins. SOCIAL LOGIN (Google / GitHub OAuth — 'Continue with Google' buttons): to start, send the browser to `${API}/auth/oauth/google` (or `/auth/oauth/github`) — a plain LINK or `location.href`, NOT fetch (it's a full-page redirect). Optional `?return=<path>` picks where to land after (defaults to the app root). The platform runs the whole OAuth dance server-side and redirects back to `/s/<slug>/<return>#token=<jwt>`; so on EVERY page load, if `location.hash` has `#token=…`, grab it (`new URLSearchParams(location.hash.slice(1)).get('token')`), `store.set(K, token)`, strip the hash (`history.replaceState(null,'',location.pathname)`), then proceed as a normal logged-in session (the token works at `/auth/me` and everywhere a password token does; the account is auto-verified). Requires the OWNER to add `GOOGLE_CLIENT_ID`+`GOOGLE_CLIENT_SECRET` (and/or `GITHUB_CLIENT_ID`+`GITHUB_CLIENT_SECRET`) in Cloud → Secrets and register the redirect URI `https://<this-site>/api/db/<slug>/auth/oauth/<provider>/callback` with the provider — TELL the user this; until then those buttons return a clear 'not set up' message (so only add social buttons when asked, and mention the setup). Password signup/login and social login share the same `_users`, so a member can use either. TWO-FACTOR (TOTP authenticator apps — Google Authenticator / Authy / 1Password): `POST ${API}/auth/2fa/setup` (Bearer) → `{secret, otpauth}` (show the `otpauth` as a QR + the secret to type); `POST ${API}/auth/2fa/enable {code}` confirms the first code and turns it on; `POST ${API}/auth/2fa/disable {code}` turns it off. Once ON, LOGIN needs the code too — if `POST ${API}/auth/login` returns `{ok:false, need:'2fa'}` (401), prompt for the 6-digit code and re-POST login with `{email,password,code}`. " +
  "PROFILES (a member's PUBLIC identity — display name, avatar, bio — so you show WHO posted WITHOUT copying an author name into every row): signup optionally takes `display_name` (`{email,password,display_name}`; else it defaults from the email). `GET ${API}/profile/<userId>` → public `{id,display_name,avatar_url,bio}`; `GET ${API}/profile/me` (Bearer) → own; `PATCH ${API}/profile/me {display_name?,avatar_url?,bio?}` edits own (build a simple 'Edit profile' form for this). **To show authors on a feed, DON'T store an author_name column — add `?authors=1` to the list read and each row comes back with `row.author = {id,display_name,avatar_url}` (its poster, by owner_id), batched.** Batch fetch arbitrary members with `GET ${API}/profiles?ids=1,2,3`. " +
  "FOLLOWS (a member follows another — the social graph behind followers/following counts and follow buttons): `POST ${API}/follow/<userId>` (Bearer) TOGGLES → `{following, followers}` (pass `{on:true|false}` to force a direction); `GET ${API}/follow/<userId>` → `{followers, following, mine}` (send the Bearer so `mine` = whether YOU follow them). Build 'Followers'/'Following' pages with `GET ${API}/follow/<userId>/followers` and `/following` → arrays of public profiles `{id,display_name,avatar_url,bio}`. You can't follow yourself; dedup is automatic (one edge per pair, no side table). **HOME FEED: on a `feed` list read, a signed-in caller adds `?following=1` to get ONLY posts by members they follow (the classic home/timeline) — composes with `where`/`q`/`sort`/pagination; empty if they follow nobody, ignored when signed out.** " +
  "BLOCK / MUTE (a member hides another): `POST ${API}/block/<userId>` (Bearer) toggles a block → `{blocking}` (and severs any follow between the two); `GET ${API}/block/<userId>` → `{blocking}`; `GET ${API}/blocks` → your blocked user ids. Then add `?hideBlocked=1` to a `feed` list read (Bearer) to drop posts by anyone you've blocked (composes with `?following=1`), and pass it on `${API}/feed?table=…` to drop blocked authors from the home timeline too. A block also STOPS DMs: a member you've blocked can no longer send you a direct message (their `POST ${API}/dm` to you → 403 `{code:'blocked'}`) — it's one-directional, so YOU can still message them. " +
  "PRESENCE / ONLINE (show who's active now — a chat sidebar, a collab room, an 'active members' list): the signed-in member sends a heartbeat `POST ${API}/presence` every ~60s while the tab is active; `GET ${API}/presence[?within=5]` → members seen in the last N minutes `[{id,display_name,avatar_url,last_seen}]`; `GET ${API}/presence/<userId>` → `{online, last_seen}` for one. " +
  "APP SETTINGS / CONFIG (site-wide settings, feature flags, theme, editable hero text — a single key→value store per app, NOT per-row data): `GET ${API}/config` → `{config:{…}}` or `GET ${API}/config/<key>` → `{value}` (PUBLIC, so the app reads these to render). Set with `POST ${API}/config/<key> {value}`; remove with `DELETE ${API}/config/<key>` — BOTH require an ADMIN site-user (only the app's admin edits settings). Values are JSON, so booleans/numbers/objects round-trip (`{value:true}`, `{value:42}`, `{value:{...}}`). Use this for global switches/feature-flags/branding; use a real TABLE for records. API KEYS (server-to-server / app-to-app access — let ANOTHER backend read+write this app's data without a member login): an admin mints a key with `POST ${API}/apikeys {label, rpm?}` → `{key:'sk_…', rpm}` shown ONCE (store it then; optional `rpm` caps THAT key at N requests/minute across all tables — over the cap → 429, omit for unlimited), `GET ${API}/apikeys` lists them (prefix + label + rpm only, never the secret), `DELETE ${API}/apikeys/<id>` revokes. The other server calls the data API with header `X-API-Key: sk_…` (instead of a Bearer token) and acts as the admin who minted it (full read/write). Manage these on an admin-only settings screen; NEVER embed a key in client-side page JS — it's a secret, treat it like a password. " +
  "SAVED VIEWS / FILTERS (let a member save and reuse a filter set / saved search / dashboard config): `POST ${API}/views/<name> {spec}` (Bearer) saves an arbitrary-JSON view; `GET ${API}/views` → their saved views `[{name,spec,created_at}]`; `GET ${API}/views/<name>` → one spec; `DELETE ${API}/views/<name>` removes it. Put the current filter/query params in `spec` and re-apply them when the member picks a view. Private per member. " +
  "BOOKMARKS / SAVES (a member's PRIVATE 'save for later' — favourites, a wishlist, a reading list — over any row): `POST ${API}/save/<table>:<id>` (Bearer) TOGGLES a save → `{saved, count}` (`{on:true|false}` forces); `GET ${API}/save/<table>:<id>` → `{count, mine}` (Bearer → whether YOU saved it). List the caller's own saves with `GET ${API}/saves[?table=<t>]` → `[{target, table, id, created_at}]` newest-first — then load those rows with `?where=id:in:<ids>`. Target is `<tableName>:<id>` (same convention as reactions). Deduped per member; no side table needed. " +
  "REPORTS / MODERATION (let members flag bad content — spam, abuse — and give the app ADMIN a queue to review): `POST ${API}/report/<table>:<id> {reason}` (Bearer) flags a row → `{reported, count}`; `GET ${API}/report/<target>` → `{count, mine}`. The admin moderation queue: `GET ${API}/reports[?status=open|resolved|dismissed|all]` (ADMIN Bearer) → the flagged items with reporter name + reason; resolve one with `POST ${API}/reports/<id> {action:'resolve'|'dismiss'|'reopen'}`. Deduped one-flag-per-member; build a simple admin 'Reports' page from the queue. ACTIVITY NOTES / LOGGING (a CRM activity log against a record — logged calls, emails, meeting notes, follow-ups on a contact/lead/deal; also works as internal comments on any row): `POST ${API}/rows/<t>/<id>/notes {body, kind?}` (Bearer) logs a note — `kind` is one of note|call|email|meeting|task|sms|log (default note); `GET ${API}/rows/<t>/<id>/notes[?kind=&limit=]` returns them newest-first, each with the author's public profile under `note.author`; `DELETE ${API}/rows/<t>/<id>/notes/<noteId>` removes your OWN note (an admin removes any). A member must be able to SEE the record to read/add notes — on a `user` table that's the owner, its owner's manager (`teamRead`), or an admin; on a public-read table (display/feed/admin) any signed-in member; write-only `collect` tables have no notes. Use it to render a record's activity timeline and log touches — no schema declaration needed, it's available on every non-collect table. FILE ATTACHMENTS (attach a contract PDF, proposal, image to a record): `POST ${API}/rows/<t>/<id>/attach {filename, content_type?, data:<base64>}` (Bearer; `data` may be a `data:` URL — the prefix is stripped; ≤~10 MB) stores the file and returns `{attachment:{id, filename, size, url, …}}`; `GET ${API}/rows/<t>/<id>/attach` lists a record's attachments (metadata + `url` each); `DELETE ${API}/rows/<t>/<id>/attach/<attId>` removes your own (admin any). Fetch the bytes back at the returned `url` (`${API}/attach/<attId>`) — it streams the file through the server with its content-type, and access follows the RECORD's visibility (a public-read row's file is public; a `user` row's file only its owner/team/admin — send the Bearer token). A member must be able to SEE the record to attach/list; not available on `collect` tables; 50 files/record. No schema declaration needed. Add `?sign=1[&ttl=<seconds>]` to the LIST call and each attachment also gets a `signed_url` — an expiring link (default 1h, max 7d) that opens the file WITHOUT a token, for embedding a private file in an email, an `<img src>`, or a share link. STORAGE USAGE (an admin dashboard of how much file storage the app is using): `GET ${API}/storage` (admin Bearer) → `{attachments:{count, bytes}, by_table:[{table, count, bytes}]}` — total attachment count + bytes site-wide and per table. Render a usage bar or per-object breakdown from it. UNIFIED TIMELINE (render a record's whole history panel in ONE call): `GET ${API}/rows/<t>/<id>/timeline[?types=&limit=]` merges that record's notes, approval decisions, and — when the table declares `\"audit\":true` — its field-change audit events into ONE reverse-chronological feed. Each entry has `{type:'note'|'approval'|'audit', at (ISO), actor_id, actor:{display_name,avatar_url}, …}` plus type-specific fields (note→kind/body, approval→action/note, audit→action). Narrow the sources with `?types=note,approval` and cap with `?limit=`. Same visibility gate as notes. Use this for the activity/history sidebar instead of stitching notes + approvals client-side." +
  "COUPONS / DISCOUNT CODES (a redeemable promo code with a usage cap + expiry): the app ADMIN mints codes `POST ${API}/coupons {code, discount, max_uses?, expires_at?}` (`discount` is your OWN JSON — `{percent:10}`, `{amount:500}`, `{freeShipping:true}`), lists `GET ${API}/coupons`, removes `DELETE ${API}/coupons/<code>`. Anyone VALIDATES a code (no consume) with `GET ${API}/coupon/<code>` → `{valid, discount, remaining}`; a signed-in member REDEEMS with `POST ${API}/coupon/<code>/redeem` → `{ok, discount}` (atomic, so the usage cap is race-free) or 409 when expired/used-up. " +
  "CART + ORDERS (a store): the CART is ready-made — `POST ${API}/cart/<table>:<id> {qty}` (Bearer) sets an item's quantity (qty 0 removes), `GET ${API}/cart` → `{cart:[{item,table,id,qty}], count}`, `DELETE ${API}/cart/<item>` removes one, `DELETE ${API}/cart` empties it. For ORDERS, declare a `user`-access `orders` table (columns like `items` (json), `total`, `status`, `email`); on checkout read `/cart`, price it by looking each item up in its product table (server-authoritative — never trust a client price), write the order row, decrement stock with the atomic incr `{by:-1, min:0}`, apply a coupon via `/coupon/<code>/redeem`, then `DELETE ${API}/cart`. Take payment with the Stripe `checkout` FUNCTION step (owner adds their STRIPE_KEY). " +
  "AUDIT LOG (a compliance / 'who changed what' trail): add `\"audit\":true` to a TABLE → every insert/update/delete is recorded automatically (no code); the app ADMIN reads it at `GET ${API}/audit[?table=<t>&action=<a>&actor=<id>&since=&until=&limit=N&offset=N]` → `[{row_table,row_id,action,actor_id,at}]` newest-first (filter by table / exact action / actor id / time range). Actor is the row's owner on user/feed tables. " +
  "DATA EXPORT / IMPORT (admin): `GET ${API}/export/<table>[?format=csv|json]` (ADMIN Bearer) downloads the whole table as CSV/JSON. `GET ${API}/export[?limit=N]` (ADMIN) downloads the ENTIRE site's data in one JSON bundle — `{tables:{name:[rows]}, users:[…safe cols, no passwords]}` — for a one-click 'Download all data' / backup button. `POST ${API}/import/<table> {csv, mapping?, hasHeader?}` (ADMIN) bulk-loads a spreadsheet — headers that match a declared column auto-map, or pass `mapping:{\"CSV Header\":\"table_col\"}`; only declared columns are written, each row is validated, and it returns `{inserted, skipped}`. Wire an admin Export button + an Import (paste CSV / file-read) form. BULK UPDATE / DELETE (admin — change or remove MANY rows at once by a filter, in one call: 'archive all completed tasks', 'delete all drafts', 'mark everything in this category on sale'): `POST ${API}/rows/<table>/bulk {op, where, set?, all?, limit?}` (ADMIN Bearer). `op` is `\"update\"` (needs `set:{col:val,…}` of declared columns) or `\"delete\"`. `where` is an array of the SAME filter clauses as a list read (`[\"status:eq:done\",\"priority:gte:3\"]`) and is REQUIRED — to intentionally hit every row pass `all:true` instead. Returns `{op, affected}` (the row count changed). Affected rows are capped (default 1000, `limit` up to 5000). On a `trash` table a bulk delete SOFT-deletes (recoverable, `soft:true` in the response); on a non-trash table it's permanent. Use THIS instead of looping per-row PATCH/DELETE from the client. " +
  "AI (real AI features, NO key needed): `POST ${API}/ai {prompt, system?}` → `{ok,text}` (chatbot, summarize, suggest, categorize). Runs server-side on the owner's credits; show a loading state, on `{ok:false}` show `d.error`. Server-side variant = an `ai` function step. " +
  "ANALYTICS (optional): fire-and-forget `POST ${API}/track {event, path}` on page views + key actions ('signup','purchase') so the owner sees traffic. No auth, no response handling. To build an IN-APP analytics dashboard (the app's OWN admin viewing that traffic), read it back with `GET ${API}/analytics[?days=14 | from=YYYY-MM-DD&to=YYYY-MM-DD][&event=&path=]` (ADMIN Bearer) → `{total, from, to, byEvent:{event:count}, byPath:[{path,n}] (top 50), series:[{day,n}] (a zero-filled daily time-series for charts — one point per day, gaps = 0), events:[distinct event names]}`. Filter to one `event` or `path`; window defaults to the last 14 days (max 90) or pass an explicit `from`/`to`. Admin-only (traffic is business data). Use the `series` straight in a line/bar chart and `byPath`/`byEvent` for top-lists. CONVERSION FUNNEL (how many people make it through an ordered flow — signup → activate → purchase, or add-to-cart → checkout → paid): log a row per actor per step into an event-log table (a `feed` table with an `event` text column works — each member owns their rows), then read `GET ${API}/funnel?table=<t>&steps=signup,activate,purchase[&step_col=event&actor=owner_id&from=YYYY-MM-DD&to=YYYY-MM-DD]` (ADMIN Bearer) → `{steps:[{step, count, pct_of_top, pct_of_prev}], overall_conversion}`. For each step it counts DISTINCT actors who completed THAT step and every step before it (so it's a real monotonic funnel with drop-off — `pct_of_prev` is the step-to-step conversion, `pct_of_top` is vs the first step), repeated steps are de-duplicated, and steps outside your list are ignored. `step_col` defaults to 'event' and `actor` to 'owner_id' (override if your columns differ — both must be columns on the table). Admin-only. Use THIS for drop-off/conversion instead of counting each step separately (which double-counts and can't tell who advanced). RETENTION COHORTS (do people come BACK — of the users first seen in a period, what % return in later periods): over the same kind of event-log table (any row by an actor = 'active that period'), `GET ${API}/retention?table=<t>[&period=week&offsets=8&actor=owner_id&from=&to=]` (ADMIN Bearer) → `{period, offsets, cohorts:[{cohort, size, retention:[{offset, count, pct}]}], overall:[{offset,count,pct}]}`. Each actor is grouped into the cohort of their FIRST activity; `retention[o]` is how many of that cohort were active again `o` periods later (offset 0 = the cohort period, always 100%). `period` is day|week|month; `overall` is the size-weighted curve across all cohorts. Render it as the classic triangular retention heatmap (`cohort` rows × `offset` columns, shade by `pct`). Admin-only. Use THIS to see stickiness/repeat-usage over time, which a funnel (one-time flow) can't show. KPI SNAPSHOTS (track a business number over time — MRR, active users, NPS, conversion rate — with deltas): record `POST ${API}/kpi {metric, value, at?, note?}` (ADMIN Bearer) whenever you have a fresh reading (`at` defaults to now; `value` is any number, fractions OK). Read one metric's trend with `GET ${API}/kpi/<metric>[?from=&to=&limit=]` → `{points:[{value,note,at}] (oldest→newest), latest, previous, change, pct_change, min, max}`, or `GET ${API}/kpi` for every metric's latest value + delta vs its previous snapshot (`{metrics:[{metric, latest, previous, change, pct_change, at, count}]}`). `DELETE ${API}/kpi/<metric>` clears a metric's history. Admin-only. Use THIS for a metrics/stat dashboard (chart the `points`, show the `pct_change` as an up/down badge) — it's for numbers YOU compute and snapshot, vs `/analytics` which counts `/track` events automatically. OUTBOUND WEBHOOKS (notify an external service — Zapier / Slack / a CRM — when something happens in your app): an admin registers subscriber URLs then the app fires events to them. `POST ${API}/webhooks {url, events?, secret?}` (ADMIN Bearer) registers a subscriber (`url` MUST be https and public — localhost/private IPs are rejected; `events` is an array like `[\"order.created\",\"signup\"]` or omit/`\"*\"` for all; a `secret` turns on HMAC signing). `GET ${API}/webhooks` lists them (the secret is NEVER returned), `DELETE ${API}/webhooks/<id>` removes one. Fire an event with `POST ${API}/webhooks/emit {event, data}` (ADMIN) — the server POSTs `{event, data, at}` as JSON to every matching subscriber and returns `{matched, delivered, results:[{hook_id, ok, status}]}`. Each subscriber receives headers `X-Webhook-Event` and, when a secret was set, `X-Webhook-Signature: sha256=<hmac of the raw body>` (the receiver recomputes it to verify authenticity). Review attempts at `GET ${API}/webhooks/deliveries[?hook=&limit=]` (a log of ok/status/error per delivery). Admin-only. Use THIS to push events OUT to other systems; use the app's own tables/notifications for in-app reactions. AUTO-FIRE ON ROW CHANGES: add `\"webhooks\":true` to a TABLE and every create/update/delete on it AUTOMATICALLY fires `<table>.created` / `<table>.updated` / `<table>.deleted` to matching subscribers (no `/emit` call needed) — the payload's `data` is the row (`created` includes the new `id` + `owner_id` + submitted fields; `updated` the id + changed fields; `deleted` just `{id}`). Opt into only some actions with `\"webhooks\":[\"created\",\"deleted\"]`. So an app subscribes an external URL to `[\"orders.created\"]` and every new order POSTed to the `orders` table is delivered automatically. (Auto-fire covers single-row writes; bulk/batch inserts + upserts don't auto-fire — call `/webhooks/emit` for those.) " +
  "SAVED SEGMENTS / AUDIENCES (save a named filter over a table — 'active users', 'big spenders', 'trials expiring' — and re-count/preview it any time): `POST ${API}/segments {name, table, filter}` (ADMIN Bearer) where `filter` is either a query string (`\"where=plan:eq:pro&where=spend:gte:500\"`) or an object (`{where:[\"plan:eq:pro\",\"active:eq:1\"]}`) using the SAME where/q/sort grammar as a list read. `GET ${API}/segments` lists them, `GET ${API}/segments/<name>` returns one, `GET ${API}/segments/<name>/count` → `{count}` of matching rows right now, `GET ${API}/segments/<name>/preview[?limit=]` → sample matching rows, `DELETE ${API}/segments/<name>` removes it. Re-saving a name updates it. Evaluated as admin over ALL rows (trashed rows excluded), so it's an audience/marketing tool — pair a segment's members with `/webhooks/emit` or an export. Admin-only. Use THIS for reusable saved audiences instead of re-typing the same filter. " +
  "TEAMS / ORGANIZATIONS / WORKSPACES (group members into shared teams with a role each — the foundation for any B2B / multi-tenant app: a workspace, a project team, an org account): a signed-in member creates a team with `POST ${API}/teams {name}` (they become its `owner`) and lists the teams they're in with `GET ${API}/teams` → `[{id, name, role, members}]`. `GET ${API}/teams/<id>` → `{team:{…, my_role}, members:[{user_id, role, display_name, avatar_url}]}` (members only — a non-member gets 403). Roles are `owner` › `admin` › `member`: `POST ${API}/teams/<id>/members {user, role?}` adds a member (owner/admin; only the owner may grant `admin`), `PATCH ${API}/teams/<id>/members/<userId> {role}` changes a role — including `role:'owner'` to TRANSFER ownership (the caller-owner is demoted to admin) — owner-only, `DELETE ${API}/teams/<id>/members/<userId>` removes someone (owner/admin; nobody can remove the owner). `POST ${API}/teams/<id>/leave` leaves (the owner must transfer or delete first), `PATCH ${API}/teams/<id> {name}` renames, `DELETE ${API}/teams/<id>` deletes the whole team (owner-only). To SCOPE data to a team, add a `team_id` column to your table, set it on create, and filter reads by the caller's team ids (from `GET ${API}/teams`); enforce writes with a membership check on the server side of your own logic. Deleting an account removes that person's memberships automatically. INVITE BY EMAIL (the normal way to grow a team — you rarely know someone's user id): an owner/admin invites with `POST ${API}/teams/<id>/invites {email, role?}` (only the owner may invite an `admin`; inviting a current member → 409); `GET ${API}/teams/<id>/invites` lists the team's pending invites and `DELETE ${API}/teams/<id>/invites/<inviteId>` revokes one. The INVITEE (any signed-in member) sees invites addressed to their email with `GET ${API}/teams/invites/mine` → `[{id, team_id, team_name, role, invited_by}]`, and acts with `POST ${API}/teams/invites/<id>/accept` (joins the team as the invited role) or `POST ${API}/teams/invites/<id>/decline`. Accept/decline require the caller's email to match the invite. So the flow is: invite by email → the person signs up (or is already a member) → they see it under `/teams/invites/mine` → accept. Build a 'Pending invitations' banner from `/teams/invites/mine`. (The invite is stored server-side; to also EMAIL the person a link, pair it with an `email` function step.) PER-TEAM SETTINGS (each workspace configures ITSELF — branding, preferences, feature flags — separate from the site-wide `/config`): `GET ${API}/teams/<id>/config` → `{config:{key:value}}` and `GET ${API}/teams/<id>/config/<key>` → `{key, value}` (any member reads); `POST ${API}/teams/<id>/config/<key> {value}` sets and `DELETE ${API}/teams/<id>/config/<key>` removes (owner/admin only). Values are JSON, so booleans/numbers/objects round-trip. Config is isolated per team and cleared when the team is deleted. Use THIS for per-workspace settings in a multi-tenant app (each team's theme, plan limits, integrations) instead of one global config. TEAM-SCOPED DATA (a table whose rows are SHARED across a team — a shared CRM, a team task board, workspace docs): add `\"teamScope\":true` to a `user`-access TABLE. Then every row is stamped with a `team_id` on create (the member MUST pass `team_id` of a team they belong to — else 400/403 `{code:'team'}`), and READS are shared: any member of that team sees EVERY row whose team_id is one of their teams (not just their own). WRITES stay author-scoped — only the row's creator can edit/delete it (a teammate can read but not change it), so it's safe by default. A member in no team sees nothing. Rows come back with their `team_id`. Combine with `/teams` (create/join) + `/teams/<id>/config`. (Batch/upsert insert isn't supported on a teamScope table — insert one row at a time with its team_id.) Use THIS for genuinely shared team data instead of owner-private `user` rows or public `feed` rows. " +
  "DOUBLE-ENTRY LEDGER (accounting / bookkeeping for an ERP, invoicing app, or finance dashboard — a real general journal, NOT just a `transactions` table): ADMIN-only, `${API}/ledger/*`. POST a BALANCED entry `${API}/ledger/entries {ref?, memo?, date?, ledger?, lines:[{account, debit?, credit?, dim?, memo?}]}` — every entry is a set of debit/credit lines where Σdebit MUST equal Σcredit (each line puts an amount on exactly one side), e.g. a $100 cash sale is `lines:[{account:'cash',debit:100},{account:'revenue',credit:100}]`; a non-balancing entry is REFUSED (400). Entries are APPEND-ONLY + IMMUTABLE — never edited/deleted, only REVERSED: `POST ${API}/ledger/entries/<id>/reverse {memo?}` posts a mirror entry (a double-reverse → 409). Read balances with `GET ${API}/ledger/balance?account=<a>[&from=&to=&dim=]` → `{debit,credit,balance}` (balance = debit−credit, posted lines only), or the whole `GET ${API}/ledger/trial-balance[?from=&to=]` → every account's `{debit,credit,balance}` + `total_debit/total_credit/balanced`. List/inspect with `GET ${API}/ledger/entries[?account=&ref=&from=&to=]` and `GET ${API}/ledger/entries/<id>`. Use `dim` for a cost-center/project dimension, and `ledger` (default 'gl') to keep separate journals (a general ledger + AP/AR/inventory subledgers) in one app. Money is kept exact to the cent. Use THIS for anything that must tie out (accounts, invoices→payments, expense tracking) instead of summing a plain table — the balance invariant + immutability are the point. PERIOD CLOSE (freeze finalized books so nobody backdates into a closed month — the accounting 'lock date'): `POST ${API}/periods/close {through:'2026-01-31'}` closes the ledger through that date — any entry OR reversal dated on/before it is then REFUSED (409 `period_locked`), so post corrections into the current open period instead. `POST ${API}/periods/reopen` clears the lock (or `{through}` moves it earlier). `GET ${API}/periods` shows the current `lock_through` + any named periods you define with `POST ${API}/periods {name,start,end}`. Applies to the ledger only. RECURRING JOURNALS (save a balanced entry once, post it every month — rent, accruals, standing charges): `POST ${API}/ledger/templates {name, memo?, ledger?, lines:[…]}` saves a template (the lines must balance, checked now so posting always works); `GET ${API}/ledger/templates` lists them, `GET/DELETE ${API}/ledger/templates/<id>` fetch/remove one, and `POST ${API}/ledger/templates/<id>/post {date?, memo?}` fires it as a fresh dated ledger entry (respects the period lock). FINANCIAL STATEMENTS (a real P&L + balance sheet, not a hand-rolled sum): first CLASSIFY accounts — `POST ${API}/ledger/accounts {account, type, name?, code?}` where type is `asset|liability|equity|income|expense` (`GET ${API}/ledger/accounts` lists, `DELETE ${API}/ledger/accounts/<account>` unclassifies). Then `GET ${API}/ledger/pnl?from=&to=` → `{income:[…], total_income, expenses:[…], total_expenses, net_income}` for the period, and `GET ${API}/ledger/balance-sheet?as_of=` → `{assets, total_assets, liabilities, total_liabilities, equity, total_equity, retained_earnings, total_liabilities_and_equity, balanced}` (current earnings roll into equity, so a fully-classified set has `balanced:true` — any unclassified account with activity is surfaced in `unclassified` and flips `balanced` false so nothing is silently dropped). BUDGETS VS ACTUALS (set targets, compare to reality): `POST ${API}/ledger/budgets {account, period, amount, notes?}` sets a target for an account in a named period (e.g. '2026-q1'; upserts), `GET ${API}/ledger/budgets[?period=]` lists, `DELETE ${API}/ledger/budgets/<id>` removes. `GET ${API}/ledger/budget-report?period=<label>&from=&to=` compares that period's budgets against the ledger actuals over from..to → `{lines:[{account, type, budget, actual, variance, pct}], totals}` (variance oriented by account type so over/under reads naturally; unbudgeted income/expense activity still surfaces, balance-sheet accounts don't). DEPRECIATION (a fixed-asset schedule — how much an asset writes off each period): `POST ${API}/finance/depreciation {cost, salvage?, life, method?, factor?, start?, freq?}` returns `{total_depreciable, schedule:[{period, date?, depreciation, accumulated, book_value}]}`; method `straight_line` (default, even) or `declining_balance` (front-loaded, factor default 2). It ties out to the cent (book value ends exactly at salvage). LOAN AMORTIZATION (a repayment schedule for a mortgage / auto loan / BNPL / any loan-management app): `POST ${API}/finance/amortization {principal, rate, term, freq?, extra?, start?}` → `{payment, periods, total_interest, total_paid, schedule:[{period, date?, payment, interest, principal, balance}]}`. `rate` is the ANNUAL percentage (e.g. 6 = 6% APR), `term` is the number of payments (360 = a 30-year monthly loan), `freq` is payments/year (default 12 = monthly). It's a level-payment (annuity) loan that ties out to the cent — the balance ends exactly at 0. Pass `extra` (extra principal per period) to model early payoff — the loan finishes in fewer `periods` with less `total_interest`. `start` + `freq` stamps each row's due `date`. Stateless (any signed-in member). Use THIS for a loan schedule instead of hand-rolling interest math; post each period's interest + principal to the ledger. INVESTMENT / CAPITAL BUDGETING (should we do this project? — NPV, IRR, payback for FP&A/CPM/EPM analysis): `POST ${API}/finance/investment {cashflows, rate}` where `cashflows` is an array of per-period net amounts (index 0 = today, usually the negative up-front investment, then each period's inflow/outflow) and `rate` is the discount/hurdle rate as a percent (10 = 10%). Returns `{npv, irr, irr_pct, payback_period, discounted_payback, profitability_index, total_inflow, total_outflow, periods}`. `npv` is the net present value at your rate (positive = creates value); `irr`/`irr_pct` is the break-even rate solved numerically (null if the flows never cross zero); `payback_period` is when cumulative cashflow turns positive (fractional; `discounted_payback` on discounted flows); `profitability_index` = PV(inflows)/PV(outflows) (>1 = worth it). Cashflows may be numbers or `{amount}` objects. Stateless. Use THIS to rank projects / evaluate an investment instead of eyeballing raw cashflows. EOQ / INVENTORY PLANNING (how much to order and when — for IMS/SCM/WMS): `POST ${API}/finance/eoq {demand, order_cost, holding_cost[, lead_time, demand_std, service_level | safety_stock]}` → `{eoq, eoq_rounded, orders_per_year, cycle_time_days, annual_order_cost, annual_holding_cost, total_annual_cost}` — the cost-minimizing order quantity (√(2·D·S/H)) where `demand` is annual, `order_cost` is per order, `holding_cost` is per unit per year. Add a `lead_time` (days) to also get `{demand_during_lead, safety_stock, reorder_point, z}` — safety stock comes from a `service_level` (e.g. 95) + daily `demand_std`, or pass `safety_stock` directly. Stateless. Pairs with the reorder-rules + stock system. BREAK-EVEN / CVP (how many to sell to be profitable — pricing & planning): `POST ${API}/finance/breakeven {price, variable_cost, fixed_cost[, target_profit, units]}` → `{contribution_margin, cm_ratio, break_even_units, break_even_units_rounded, break_even_revenue}`. Give `target_profit` to also get the units to hit that profit; give a `units` volume to get `{profit_at_units, margin_of_safety_units, margin_of_safety_pct}`. Contribution margin = price − variable cost; break-even needs price > variable cost. Stateless. Use THIS for a pricing/what-if calculator. Store the asset in a normal table, show this schedule, and post each period with a recurring journal. Any signed-in member (stateless calc). DEMAND FORECAST (project future demand/sales from history — for planning + reorder): `POST ${API}/finance/forecast {series:[numbers or {value}], method?, horizon?, window?, alpha?}` → `{forecast:[{step, value}]}` for the next `horizon` periods. method `linear` (default, least-squares trend), `moving_average` (flat mean of the last `window`), or `exp_smoothing` (weighted recent, `alpha`). Feed the forecast against on-hand + reorder rules to plan purchasing. Stateless calc (any signed-in member). SALES TAX / VAT (compute tax on an order — invoice/POS/checkout): `POST ${API}/finance/tax {subtotal, rate | rates:[{name?, rate, compound?}], inclusive?}` → `{subtotal, tax, total, taxes:[{name, rate, amount}]}`. Pass one `rate` or a `rates[]` of jurisdictions (state + county + city); an additive rate charges on the subtotal, a `compound:true` rate charges on subtotal + prior taxes (tax-on-tax). `inclusive:true` treats the given `subtotal` as tax-INCLUSIVE and backs out the net (the per-jurisdiction split ties to the cent). Cents-exact, stateless (any signed-in member). Use THIS for order tax instead of multiplying in the browser. INSTALLMENTS / PAYMENT PLAN (BNPL, layaway, pay-over-time): `POST ${API}/finance/installments {total, count, down?, rate?, freq?, start?}` → `{payment, count, total_interest, total_paid, schedule:[{n, date?, amount, interest, principal, balance}]}`. Splits `total` (minus an optional `down`) into `count` payments; `rate` 0 = an equal split, `rate` > 0 = an amortized annuity that reuses the loan tie-out (the final payment clears the balance to exactly 0). `start` + `freq` (payments/year, default 12) stamp each row's due date. Stateless. TIERED / MARGINAL COMMISSION (sales comp, payroll, SPM): `POST ${API}/finance/commission {amount, rate | brackets:[{up_to?, rate}], base?}` → `{commission, effective_rate, brackets:[{from, to, rate, portion, commission}]}`. A flat `rate`, or marginal `brackets` where each bracket's rate applies ONLY to the portion of `amount` inside it (like income-tax brackets; the last bracket omits `up_to` = open-ended), plus an optional flat `base`. Cents-exact, stateless. Use THIS for tiered payout math instead of hand-rolling bracket logic. LEAVE / PTO BALANCES (HR — track annual/sick leave without overdrawing): ADMIN-only, `${API}/leave/*`. `POST ${API}/leave {employee, leave_type?, days, kind?, note?, date?}` records an accrual (days POSITIVE) or a taking (NEGATIVE); a taking that would overdraw is refused (409) unless `allowNegative`. `GET ${API}/leave/balance?employee=<e>[&leave_type=]` → `{balance}`, `GET ${API}/leave/balances[?leave_type=]` → everyone's, `GET ${API}/leave?employee=&leave_type=` → the history. Half-days OK. (The REST of HR — employees, departments, timesheets, projects — is plain tables: use `teamRead` for a manager's view, the approval workflow for leave requests, and stats for timesheet/project cost rollups. Payroll tax calc needs an external provider.) SCHEDULING / BOOKINGS (appointments, interviews, room/resource/equipment rentals — book time slots that can't double-book): any signed-in member uses `${API}/bookings/*`. `POST ${API}/bookings {resource, start, end, party?, ref?, note?}` books a window on a resource (ISO datetimes); two overlapping bookings on the same resource are IMPOSSIBLE — the second is refused (409 `conflict`) atomically, so no double-booking even under races. `GET ${API}/bookings/availability?resource=<r>&from=&to=&slot=<minutes>[&step=]` returns the FREE slots in a window (for a 'pick a time' UI). `GET ${API}/bookings[?resource=&from=&to=&status=]` lists (a member sees their own, an admin sees all), `POST ${API}/bookings/<id>/cancel` frees a slot, `DELETE ${API}/bookings/<id>` removes it. Back-to-back slots (end == next start) are allowed. Use THIS for anything time-slot based instead of a plain table so the no-overlap guarantee is real. WALLET / POINTS / STORE CREDIT (loyalty points, store credit, gift cards, in-app currency, XP — a guarded balance): writes are ADMIN (server-authoritative, so users can't credit themselves); a member reads their OWN balance. `POST ${API}/wallet {account, currency?, amount(+earn/−spend), kind?, ref?, note?}` credits or debits — a debit that would overdraw is refused (409) unless `allowNegative`. `GET ${API}/wallet/balance?account=<a>[&currency=]` → `{balance}`, `GET ${API}/wallet?account=<a>` → the ledger history, `GET ${API}/wallet/balances` (admin) → everyone's, `POST ${API}/wallet/transfer {from, to, amount}` (admin) moves balance between accounts (guarded). `currency` namespaces independent balances (points vs credit vs a giftcard); a gift card is just an `account` keyed by the card code. Use THIS for any earn/spend balance instead of a number column that races or goes negative. PROMOTIONS / PROMO CODES (a real discount engine — the discount is computed server-side, unlike the simpler `/coupons`): an admin mints `POST ${API}/promotions {code, kind:'percent'|'fixed'|'free_shipping', value, min_order?, max_uses?, per_user_max?, starts?, expires?}`. A shopper PREVIEWS with `POST ${API}/promotions/<code>/validate {order_total, account?}` → `{valid, discount, free_shipping, reason?}` (reasons: invalid/expired/not_started/min_order/exhausted/user_limit). Applying is server-authoritative: `POST ${API}/promotions/<code>/redeem {order_total, account?, order_ref?}` (ADMIN) records a redemption ATOMICALLY so a limited code can't be oversold or reused past its per-user cap. Codes are case-insensitive. `GET ${API}/promotions[/<code>]` (admin) shows usage. Use `/promotions` when you need computed percent/fixed discounts + min-order + usage caps; use the simpler `/coupons` for an opaque discount blob. ENTITLEMENTS / SUBSCRIPTIONS (gate 'Pro' or a feature per account, with expiry — the membership STATE, not the payment): an admin grants `POST ${API}/entitlements {account, feature?, plan?, status?, expires?, meta?}` (feature omitted = the whole-account plan). The app gates with `GET ${API}/entitlements/check?account=<a>[&feature=]` → `{active, plan, expires, status}` where `active` is true only if status is active AND within any start/expiry window (so an expired plan reads inactive automatically). `GET ${API}/entitlements?account=<a>` lists all of an account's, `DELETE ${API}/entitlements/<feature>?account=` revokes. A member checks/reads their OWN; an admin any. Renew by re-granting (upsert). Use THIS to unlock features by plan instead of a boolean column you have to expire by hand. (Payments themselves are Stripe at the platform level.) REFERRALS / INVITE ATTRIBUTION (a 'refer a friend' program — who invited whom, a referral leaderboard): any signed-in member. `POST ${API}/referrals/code` returns MY stable referral code (deterministic, get-or-create — share it in an invite link). A newly-signed-up member attributes themselves with `POST ${API}/referrals/claim {code}` → `{referrer_id}` — this can happen exactly ONCE per member (a second claim, or switching codes, → 409; you can't claim your OWN code → 400; unknown → 404), enforced atomically so it can't be double-counted under races. `GET ${API}/referrals/mine` → `{code, referred_count, referred:[{user_id, at}]}` (who I've brought in), and `GET ${API}/referrals/leaderboard[?limit=]` (ADMIN) ranks the top referrers. Use THIS for invite/referral tracking instead of a nullable `referred_by` column that anyone can overwrite. Grant the reward yourself (wallet/points/entitlement) off the claim. FEATURE FLAGS (turn features on/off per user without a redeploy — gradual rollouts, betas, kill switches): an admin configures flags, every member evaluates which are on for THEM. `POST ${API}/flags {key, enabled?, rollout?(0-100), roles?[], teams?[], value?}` (ADMIN) upserts a flag; `rollout` is a percent (a member is deterministically bucketed by a stable hash of key+their id, so raising the % only ever adds users, and a member is consistently in/out), `roles`/`teams` restrict it to certain roles or teams, and `value` is an optional JSON payload delivered when the flag is on (for a variant/config). The app gates with `GET ${API}/flags/eval?key=<k>` → `{on, value}` for one flag, or `GET ${API}/flags/eval` → `{flags:[{key, on, value}]}` for all — open to any signed-in member. An unknown/deleted flag evaluates to `on:false` (never errors), so you can gate on any key safely. `GET ${API}/flags` (admin) lists every flag + config, `DELETE ${API}/flags/<key>` (admin) removes one. A flag is ON iff enabled AND role matches AND team matches AND the member is in the rollout bucket. Use THIS for staged rollouts / betas / A-B gating instead of a hardcoded boolean, and DISTINCT from the static public `/config` KV (that's read verbatim; this is evaluated per user). SAVED SEARCHES (per-member — a member names a filter over a table and re-runs it, e.g. their open tickets, listings under a price cap, a saved report): `POST ${API}/searches {name, table, query}` saves it (query is a list query-string like `where=status:eq:open&sort=created_at&order=desc`, or an object `{where:[…], q, sort, order, limit}`); `GET ${API}/searches[?table=]` lists mine; `GET ${API}/searches/<name>/run[?limit=&offset=]` RUNS it → `{total, rows}`; `GET ${API}/searches/<name>` returns its metadata; `DELETE ${API}/searches/<name>` removes it. Each member's searches are PRIVATE (keyed to them — another member's is a 404 to you), and RUN executes under the CALLER's own read scope (their own rows on a `user` table, public rows on display/feed, refused on write-only `collect`; trashed/expired/unpublished/archived rows always hidden) — so a saved search can never surface a row the member couldn't read directly. Use THIS to let members keep reusable filtered views instead of re-passing the same query params every time; it's the per-member cousin of admin `/segments` (which build audiences over ALL rows). RATINGS & REVIEWS (star ratings + written reviews on any subject — products, listings, anything): `POST ${API}/reviews {subject, rating(1-5), title?, body?}` upserts MY review for a subject (one per member; re-posting edits it). Reads are PUBLIC: `GET ${API}/reviews?subject=<s>[&sort=recent|top&limit=&offset=]` lists them and `GET ${API}/reviews/summary?subject=<s>` returns `{count, average, distribution:{1..5}}` computed in SQL. `GET ${API}/reviews/mine?subject=<s>` is my own review; `DELETE ${API}/reviews?subject=<s>` removes mine (an admin may add `&user=<id>` to moderate any). Use THIS for a rating/review widget instead of a plain table — the one-per-member rule and the aggregate are handled. WAITLIST / QUEUE (a fair first-come signup queue — early access, a drop, limited slots): any member. `POST ${API}/waitlist/<list>/join` puts me on the named list once → `{position, seq}`; `GET ${API}/waitlist/<list>/me` is my live `{status, position}` (position advances as people ahead leave or are let in); `POST ${API}/waitlist/<list>/leave` removes me. An admin runs it: `GET ${API}/waitlist/<list>` is the ordered queue + counts, and `POST ${API}/waitlist/<list>/claim {user?, as?}` lets in the front (or a named member), dropping them from the waiting count so everyone behind moves up. Positions are atomic (no two members ever get the same slot). Use THIS for any waitlist/queue instead of a table you hand-rank. DAILY CHECK-IN STREAKS (habit tracker / gamification — a Duolingo-style streak): any member. `POST ${API}/streak/checkin` records today (at most once per UTC day; a repeat is a harmless no-op) → `{checked_in, current_streak, longest_streak, total}`; `GET ${API}/streak` returns those plus the recent check-in days. current_streak is the run ending today or yesterday, longest_streak the best ever. Use THIS for a streak/consistency feature instead of computing consecutive days yourself. REMINDERS (per-member scheduled notes the app polls for — follow-ups, nudges, due dates), all PRIVATE to the owner: `POST ${API}/reminders {remind_at, note, subject?}` schedules one; `GET ${API}/reminders` lists mine soonest-first (`?upcoming=1` future only, `?done=1` completed); `GET ${API}/reminders/due` returns the ones that have come due (poll this to surface them); `POST ${API}/reminders/<id>/done` completes one; `PATCH ${API}/reminders/<id>` edits; `DELETE ${API}/reminders/<id>` removes. Use THIS for reminders/follow-ups instead of a table you filter by time by hand — to actually alert at the due time, poll /due and raise an in-app notification (or wire a scheduled edge function). THREADED COMMENTS (a comment section on any record — posts, listings, tasks): `POST ${API}/comments {table, row, body, parent?}` adds a comment (or a reply via parent) on a (table,row); `GET ${API}/comments?table=<t>&row=<id>` returns the thread oldest-first (PUBLIC — each row carries parent_id so the client nests replies), and `GET ${API}/comments/count?table=<t>&row=<id>` the live count. A member edits their own with `PATCH ${API}/comments/<id> {body}` and soft-deletes with `DELETE ${API}/comments/<id>` (an admin may delete any). A soft-deleted comment stays as a tombstone only while it still has replies, else it disappears. Use THIS for a comment/discussion thread on any record instead of a plain table. SURVEYS / NPS / CSAT (collect a satisfaction score + comment and get the aggregate): `POST ${API}/surveys/<survey> {score, comment?, max?}` records MY response (one per member per survey; re-submitting edits it; score 0..max, max default 10). `GET ${API}/surveys/<survey>/mine` is my own response. The owner reads the aggregate `GET ${API}/surveys/<survey>/summary?kind=nps|csat|avg` (ADMIN) — nps returns promoters/passives/detractors + the NPS number, csat the average + %satisfied, avg the mean — and the raw `GET ${API}/surveys/<survey>/responses` (ADMIN). Use THIS for an NPS/CSAT/feedback score instead of a plain table — the one-per-member rule and the NPS/CSAT math are handled (distinct from /reviews, which is a public per-subject star rating). AT-MENTIONS (a who-tagged-me inbox — flag a member they were @-mentioned in a comment/post/task): when your app detects an @tag, `POST ${API}/mentions {user, ref_table?, ref_id?, context?}` records it (user = the mentioned member's id). The mentioned member reads `GET ${API}/mentions/mine[?unseen=1]` (newest-first), `GET ${API}/mentions/unseen-count` for a badge, and clears them with `POST ${API}/mentions/<id>/seen`, `POST ${API}/mentions/seen-all`, or `DELETE ${API}/mentions/<id>`. Mentions are private to the recipient. Use THIS for @mention notifications instead of scanning text yourself. EVENT REGISTRATION WITH CAPACITY (ticketed events, class signups, limited slots — sign-ups that stop at a hard cap and auto-waitlist): an admin defines an event with `POST ${API}/events/<event> {title?, capacity, starts_at?}`. A member registers with `POST ${API}/events/<event>/register` → `{status:'registered'|'waitlisted', seq}` — the seat-vs-waitlist decision is atomic so the cap is never exceeded. `GET ${API}/events/<event>` is the public status `{capacity, registered, waitlisted, spots_left}`, `GET ${API}/events/<event>/me` is my registration (+ waitlist position), `POST ${API}/events/<event>/cancel` frees my seat and auto-promotes the next person off the waitlist, and `GET ${API}/events/<event>/roster` (ADMIN) is the full list. Use THIS for anything with a fixed number of spots instead of a plain table — the no-overbooking guarantee + the waitlist promotion are the point. (For an UNBOUNDED signup queue use /waitlist; for a simple yes/no RSVP with no cap use /reactions.) FUNDRAISING / GOAL PROGRESS (a crowdfunding thermometer, a tip jar, a pledge drive with a target): an admin sets `POST ${API}/goals/<goal> {title?, target, currency?, deadline?}`. A member contributes with `POST ${API}/goals/<goal>/contribute {amount, note?}` → `{raised, progress_pct}`. `GET ${API}/goals/<goal>` is the public progress `{target, raised, progress_pct, met, contributions, contributors}` and `GET ${API}/goals` lists every goal — perfect for a progress bar. The per-contributor amounts are private (`GET ${API}/goals/<goal>/contributions` is ADMIN-only). Money is exact to the cent and over-funding past 100% is allowed. Use THIS for a fundraising/goal bar instead of summing a table yourself. (Contributions here are amounts you record — to actually CHARGE money, wire a Stripe checkout edge function and record the paid amount here on the webhook.) NOTIFICATION PREFERENCES + QUIET HOURS (let members choose which notifications they get + a do-not-disturb window): a member reads `GET ${API}/notify-prefs` and updates `POST ${API}/notify-prefs {channels?, types?, quiet_start?, quiet_end?, tz_offset?}` — channels/types are maps like `{email:true, sms:false}` and `{marketing:false, mentions:true}` (on unless set false); quiet_start/quiet_end are local hours 0–23, tz_offset is minutes from UTC. Before sending, the app asks `GET ${API}/notify-prefs/should-send?type=<t>&channel=<c>` → `{send, reasons}` (the sender, as ADMIN, may check any member with `&user=<id>`) — send is true only if that type + channel are enabled AND the member isn't in their quiet window right now (handles windows that wrap past midnight and the member's timezone). Use THIS to respect notification opt-outs + quiet hours instead of blasting everyone. ANNOUNCEMENTS (a site-wide banner/notice an admin broadcasts to everyone, dismissible per member — maintenance notices, new-feature banners, alerts): an admin posts `POST ${API}/announcements {title?, body, level?, starts_at?, ends_at?}` (level e.g. info/warning/critical; starts_at/ends_at bound when it's live). A member fetches `GET ${API}/announcements` → the ACTIVE announcements they haven't dismissed yet, and dismisses one with `POST ${API}/announcements/<id>/dismiss` (per-member — dismissing hides it only for them). An admin lists everything with `GET ${API}/announcements/all` and removes one with `DELETE ${API}/announcements/<id>`. Use THIS for a dismissible notice banner instead of hardcoding one — scheduling + per-member dismissal are handled. IDEMPOTENCY KEYS (make a repeated action run only ONCE — safe retries for a payment, an order, a webhook that might be delivered twice): before doing the work, the app calls `POST ${API}/idempotency/<key> {response?}` with a unique key. The FIRST call returns `{first:true}` (so you do the work, and can pass the result as `response` to store it); any REPLAY of the same key returns `{first:false, response:<the stored result>}` so you skip re-doing it and return the original result. `GET ${API}/idempotency/<key>` peeks, `DELETE` clears it. Keys are per-member. Use THIS to guard anything that must not double-execute instead of hoping the client never retries. CATEGORIES / TAXONOMY TREE (a nested category hierarchy — blog categories, product categories, folders): an admin builds it with `POST ${API}/categories {name, slug?, parent?, sort?}` (parent = a parent category's id; slug auto-derives from the name). Anyone reads `GET ${API}/categories` → `{flat, tree}` (the nested tree, ready to render a menu) and `GET ${API}/categories/<id>` → `{category, path, children}` (path = the breadcrumb root→node). An admin edits with `PATCH ${API}/categories/<id>` (reparenting is cycle-guarded) and removes with `DELETE ${API}/categories/<id>` (its children reparent up to its parent). Use THIS for a category/folder hierarchy instead of a flat table with a parent column you assemble by hand. NAMED LISTS / COLLECTIONS (a member curates named lists of items — a wishlist, a watchlist, a playlist, saved items across tables): `POST ${API}/lists {name, kind?, public?}` creates a list; `GET ${API}/lists` is my lists (with item counts); `GET ${API}/lists/<id>` is a list + its items (mine, or anyone's if it's public — a shareable wishlist); `PATCH ${API}/lists/<id> {name?, public?}` renames or toggles sharing; `DELETE ${API}/lists/<id>` removes it. Add/remove items with `POST ${API}/lists/<id>/items {table?, row?, note?}` and `DELETE ${API}/lists/<id>/items/<itemId>` — an item references a row (table+row) and/or carries a note. Lists are private to the owner unless made public. Use THIS for user-curated named collections (distinct from a single flat bookmarks toggle — this is multiple named lists with ordered items). ONE-TIME CODES / OTP (verify a short code — confirm a phone/email, or gate a sensitive action): `POST ${API}/otp/generate {purpose, identifier, ttl?, length?, max_attempts?}` makes a code and returns it ONCE (your app sends it to the user via an email/SMS edge function — it's stored only hashed); then `POST ${API}/otp/verify {purpose, identifier, code}` checks it → `{verified:true}` (single-use), or a miss returns `{verified:false, attempts_left}`, an expired code → 400, and too many wrong tries → 429 (locked — request a new one). `purpose` groups codes (e.g. phone, email-change) and `identifier` is what's being verified. Use THIS for confirmation codes instead of rolling your own — expiry, the attempt lockout, single-use, and hashing are handled (sending the code is yours: return it to your edge function and email/SMS it). SAVED ADDRESSES / ADDRESS BOOK (a member's shipping/billing addresses with one default — for checkout, profiles): `POST ${API}/addresses {label?, name?, line1, line2?, city?, region?, postal?, country?, phone?, default?}` saves one (line1 required; the first is auto-default); `GET ${API}/addresses` lists mine (default first); `GET`/`PATCH`/`DELETE ${API}/addresses/<id>` read/edit/remove one; `POST ${API}/addresses/<id>/default` makes it the default (exactly one, set atomically). Private per member. Use THIS for a saved-addresses picker instead of keeping the one-default invariant on a plain table yourself. PER-MEMBER SETTINGS (each member's own key→value preferences — theme, saved layout, app options; distinct from the public site `/config` and from `/notify-prefs`): `GET ${API}/settings` returns all my settings as `{key:value}`; `GET ${API}/settings/<key>` one; `POST ${API}/settings/<key> {value}` sets one (value is any JSON — string/number/object/array); `POST ${API}/settings {k:v, …}` bulk-sets several; `DELETE ${API}/settings/<key>` removes one. Private per member. Use THIS for per-user app settings instead of stuffing them in a profile column. RECENTLY-VIEWED (a per-member ring of the rows they last looked at — recently-viewed products, recent documents): call `POST ${API}/recent {table, row}` when a member opens a record; `GET ${API}/recent[?table=&limit=]` returns their recently-viewed newest-first (re-viewing bumps a row to the top, no duplicates, pruned to the last 200); `DELETE ${API}/recent[?table=&row=]` clears one or all. Private per member. Use THIS for a recently-viewed rail instead of tracking it in the browser (it follows the member across devices). FAQ / KNOWLEDGE BASE (a help section — questions & answers, categorized): an admin manages entries with `POST ${API}/faq {question, answer, category?, sort?, published?}`, `PATCH ${API}/faq/<id>`, `DELETE ${API}/faq/<id>`. Anyone reads the published ones: `GET ${API}/faq[?category=&q=]` (q searches the question + answer), `GET ${API}/faq/categories` lists the categories, and an admin sees drafts too via `GET ${API}/faq/all`. Use THIS for a FAQ/help page instead of a plain table — publish gating + search + categories are handled. BUSINESS HOURS / OPEN-NOW (weekly opening hours + holidays + an are-we-open check — for a local-business site): an admin sets weekly intervals with `POST ${API}/hours {dow(0=Sun..6=Sat), open, close}` (open/close as HH:MM; a day may have several intervals) and holiday/special overrides with `POST ${API}/hours/special {date, closed?, open?, close?}`. Anyone reads `GET ${API}/hours` → `{weekly, specials}` (render an hours table) and checks `GET ${API}/hours/open?tz=<minutesFromUTC>` → `{open, reason, closes_at}` (pass the business's timezone offset; a date override wins over the weekly schedule). Use THIS for opening hours + an open/closed badge instead of hardcoding them. A/B EXPERIMENTS (test two designs and measure which converts better — a step past a simple on/off flag): an admin defines `POST ${API}/experiments/<key> {variants:[{name, weight?}] or ['a','b'], enabled?}`. In your page, `GET ${API}/experiments/<key>/assign` → `{variant}` assigns the member to a variant deterministically + stickily (weighted; the same member always gets the same one) and records the exposure — render that variant. When the goal happens (signup, purchase), call `POST ${API}/experiments/<key>/convert`. The admin reads `GET ${API}/experiments/<key>/results` → per-variant `{exposures, conversions, rate}` to pick the winner. Use THIS to A/B-test instead of guessing; use `/flags` when you just need an on/off or % rollout with no conversion measurement. NAMED COUNTERS (atomic tallies — page-hit counts, download counts, poll votes, a live signup counter): any signed-in member `POST ${API}/counters/<name>/incr {by?}` → `{n}` bumps a named integer counter atomically (`by` defaults to 1, may be negative); anyone reads `GET ${API}/counters/<name>` → `{n}` (0 if unset) or `GET ${API}/counters` for all of them. An admin can `POST ${API}/counters/<name> {value}` to set it or `DELETE` it. Use THIS for a shared running total instead of a table you COUNT() every read — the increment is a single atomic write and the read is instant. REDIRECTS (a link-shortener or an old-URL → new-URL map with hit tracking): an admin `POST ${API}/redirects {from, to, code?}` maps a path (a leading slash is added if missing) to any URL/path with an HTTP code (301 default · 302/307/308); re-posting the same `from` updates it. At runtime `GET ${API}/redirects/resolve?from=<path>` → `{to, code}` (404 if none) and counts the hit. Admin lists all with hit counts via `GET ${API}/redirects` and removes one with `DELETE ${API}/redirects/<id>`. Use THIS for vanity links, campaign short-URLs, or migrating old paths. BADGES / ACHIEVEMENTS (award members earned badges — Early Adopter, Top Contributor, a course-completion mark): an admin defines one `POST ${API}/badges/<key> {name, description?, icon?}` (re-post to edit), then awards it to a member `POST ${API}/badges/<key>/award {user:<memberId>}` (idempotent — awarding twice is a no-op) and can revoke `DELETE ${API}/badges/<key>/award/<memberId>`. Anyone reads the catalog `GET ${API}/badges` → each badge + its holder count; a member reads their own earned set `GET ${API}/badges/mine`; an admin sees who holds one via `GET ${API}/badges/<key>/holders`. Deleting a badge removes all its awards. Use THIS for gamification/recognition instead of a boolean column per achievement. NAV / MENU BUILDER (a header/footer/sidebar navigation the owner can edit without touching code — ordered, nestable links): an admin adds items `POST ${API}/menus/<menu>/items {label, url?, parent?, position?}` → `{id}` (menu is any key like header/footer; `parent` is another item id in the SAME menu for a dropdown; `position` sorts, may be negative), edits with `PATCH ${API}/menus/<menu>/items/<id> {label?, url?, parent?, position?}`, removes with `DELETE ${API}/menus/<menu>/items/<id>` (also removes its descendants). Your page reads the whole thing as a nested tree: `GET ${API}/menus/<menu>` → `{items:[{id,label,url,position,children:[…]}]}` (already ordered + nested — render it recursively), and `GET ${API}/menus` lists the menu keys. Use THIS for editable navigation instead of hardcoding links. SEO METADATA (per-page title / meta description / OG share image / canonical / keywords the owner can set per record): an admin upserts `POST ${API}/seo {entity, ref, title?, description?, image?, canonical?, keywords?}` where (entity,ref) identifies the thing (entity:`product` ref:`42`, or entity:`page` ref:`/about`). Your page reads `GET ${API}/seo?entity=product&ref=42` → `{meta:{title,description,image,canonical,keywords}}` (or `meta:null`) and injects those into the document <head> for rich search results + social cards. Admin `GET ${API}/seo/all` lists every row; `DELETE ${API}/seo?entity=&ref=` clears one. Use THIS so each page/product has its own share preview instead of one generic site-wide tag. REUSABLE CONTENT SNIPPETS (named chunks of copy the owner edits in one place and you drop in many — a promo banner, a footer blurb, boilerplate terms): an admin upserts `POST ${API}/snippets/<slug> {title?, body, format?, published?}` (set `published:false` to stage a draft). Your page pulls one with `GET ${API}/snippets/<slug>` → `{snippet:{title,body,format}}` (published only — a draft 404s) and renders `body` (use `format` to know if it is html/markdown/plain). `GET ${API}/snippets` lists published slugs; admin `GET ${API}/snippets/all` includes drafts. Use THIS for owner-editable copy that appears in several spots instead of hardcoding the text. SUPPORT TICKETS (a help desk — customers open tickets, staff triage + reply on a thread): a signed-in member opens one `POST ${API}/tickets {subject, body, priority?}` (priority low/normal/high/urgent) → `{id}`. They list their own with `GET ${API}/tickets` and read one + its whole reply thread with `GET ${API}/tickets/<id>` → `{ticket, messages:[…]}`. Either side adds a reply `POST ${API}/tickets/<id>/messages {body, internal?}` — a member replying to a resolved/closed ticket auto-REOPENS it. Staff (an ADMIN Bearer) see EVERY ticket via `GET ${API}/tickets[?status=open&assignee=<id>&mine=1]`, can post an `internal:true` note the requester never sees, and triage with `PATCH ${API}/tickets/<id> {status?, priority?, assignee?}` (status open/pending/resolved/closed — resolving/closing stamps closed_at; assignee is a staff user id). A requester can only see/reply to their OWN ticket; internal notes are admin-only. Use THIS for customer support instead of a plain contact-form table — you get status, assignment, threaded replies, and staff-private notes. CANNED RESPONSES (a staff library of reusable reply templates to paste into ticket answers): ADMIN-only — `POST ${API}/canned/<key> {title?, body}` saves one, `GET ${API}/canned` lists them, `GET ${API}/canned/<key>` reads one, `DELETE` removes it. Build a staff-side picker that inserts `body` into the ticket reply box. Not visible to members. HELP-ARTICLE VOTES (a `Was this helpful? Yes / No` widget under a help/FAQ article): a signed-in member casts `POST ${API}/helpful/<article> {helpful:true|false}` (one vote each, changeable) and can retract with `DELETE ${API}/helpful/<article>`. Anyone reads the tally `GET ${API}/helpful/<article>` → `{yes, no, total, score, mine}` (score = % who said yes; `mine` = the caller past vote or null). `<article>` is any stable id/slug/path for the page. Use THIS to measure which docs help instead of a raw counter — you get yes vs no, a helpful %, and per-user dedup. HOME FEED / TIMELINE (a social timeline of posts from the people you follow): pairs with the follow graph (`POST ${API}/follow/<userId>`). `GET ${API}/feed?table=<t>[&limit=&before=]` returns the rows of a `feed`-access table owned by whoever the signed-in caller follows, newest-first, excluding their own + trashed rows. Keyset-paginate with the returned `next_before` (pass it as `before`). The table must be `feed` access (public rows owned by members) — a private `user` table is rejected. Use THIS for a home timeline instead of fetching all posts and filtering client-side. DIRECT MESSAGES (1:1 private chat between two members): `POST ${API}/dm {to, body}` sends (to = the other member's id); `GET ${API}/dm/<otherId>[?limit=&before=&markRead=1]` returns that conversation newest-first (both directions share one thread) — `markRead=1` clears your unread from them. `GET ${API}/dm/threads` lists your conversations (each: `with`, `last` message, `unread`), `GET ${API}/dm/unread` → total unread, `POST ${API}/dm/<otherId>/read` marks a thread read. Only the two participants can see a thread. A `POST ${API}/dm` to someone who has BLOCKED you is refused with 403 `{code:'blocked'}` — surface a 'you can't message this member' notice. Use THIS for private messaging instead of a public table anyone can read. TIME & ATTENDANCE / CLOCK (HRMS — clock in/out, worked hours): a signed-in member clocks themselves. `POST ${API}/timeclock/in {at?, note?}` opens a shift (409 if already clocked in), `POST ${API}/timeclock/out {at?}` closes it → `{minutes, hours}`; `GET ${API}/timeclock/status` → `{clocked_in, since}`. `GET ${API}/timeclock/summary?employee=&from=&to=` → total hours over a period (an admin omits `employee` to get everyone). `GET ${API}/timeclock/entries` lists shifts. An admin can pass `employee` to act for anyone, and `POST ${API}/timeclock/entry {employee, clock_in, clock_out}` adds a corrected shift. Use THIS for attendance/hours instead of a plain table so double clock-ins are impossible and hours are computed for you. EFFECTIVE-DATED RECORDS (a value that changes over time you can query 'as of' any date — salary/title history, price history): ADMIN-only, `${API}/effective`. `POST ${API}/effective {subject, attribute, effective_date, value, note?}` records a dated change (`value` is any JSON; same subject+attribute+date upserts). `GET ${API}/effective?subject=<s>&attribute=<a>&as_of=<date>` returns the value in force on that date (the latest change on/before it) with which record applied; omit `as_of` for the full history. `GET ${API}/effective/snapshot?attribute=<a>&as_of=<date>` returns EVERY subject's value as of a date (e.g. everyone's salary on a pay date). Use THIS for anything where you must know the historical value at a point in time, instead of overwriting a column and losing the past. COURSE PROGRESS (LMS — lessons, a learner's completion %, prerequisites): an admin defines a course `POST ${API}/courses/<course> {items:[{item, prereq?, sort?}]}` (a `prereq` must be another item in the course). A signed-in member records THEIR OWN progress `POST ${API}/courses/<course>/complete {item, score?}` — refused (409 `prereq`) until the item's prerequisite is done — and reads it `GET ${API}/courses/<course>/progress` → `{completed, total, percent, items:[{item, done, score}]}`. `POST ${API}/courses/<course>/reset {item?}` un-completes one item or the whole course. An admin can pass `learner` to record/read for any student (instructor view). `GET ${API}/courses` lists courses. Use THIS for lesson/module completion + gating instead of a boolean column. QUIZ AUTO-GRADING (assessments where the answer key stays SERVER-SIDE — no cheating): an admin defines `POST ${API}/quizzes/<quiz> {questions:[{qid, answer, points?}], pass_pct?}` (answer can be a value, an array of acceptable values for any-of, or an array for an exact multi-select; case/space-insensitive). A signed-in member submits `POST ${API}/quizzes/<quiz>/grade {answers:{qid:answer}}` → `{score, max, percent, passed, results:[{qid, correct}]}` — the response NEVER contains the correct answers, and `GET ${API}/quizzes/<quiz>` hides the key from non-admins (takers see qids+points only). `GET ${API}/quizzes/<quiz>/attempts` returns the learner's past attempts. Use THIS whenever scoring must be trustworthy instead of grading in the browser. LOCALIZATION / i18n (the same UI strings or content in many languages, with fallback): reads are PUBLIC (no login — a multilingual site renders to anyone). Admin loads strings `POST ${API}/i18n {locale, entries:{'home.title':'Welcome', …}, namespace?}` (or a single `{locale, key, value}`); the site fetches `GET ${API}/i18n?locale=fr&fallback=en` → `{values:{key:string}}` where any key missing in `fr` falls back to `en` — so you render one flat dictionary. `GET ${API}/i18n/<key>?locale=&fallback=` gets one string, `GET ${API}/i18n/locales` lists which languages exist, `DELETE ${API}/i18n/<key>[?locale=]` removes a translation (one locale, or all). Use `namespace` to separate string sets (UI vs emails vs a page's content). Use THIS for translations instead of duplicating columns per language. " +
  "STOCK / INVENTORY LEDGER (real warehouse stock — on-hand that can't go negative, reservations, multi-location — NOT just a `qty` number on a product row): ADMIN-only, `${API}/stock/*`. Record a movement `POST ${API}/stock/moves {item, location?, qty, kind?, ref?, unit_cost?}` — qty POSITIVE = receipt, NEGATIVE = issue; an issue that would drive on-hand below zero is REFUSED (409 insufficient stock) unless you pass `allowNegative:true`. Read `GET ${API}/stock/level?item=<i>[&location=<l>]` → `{on_hand, reserved, available}` (available = on_hand − active reservations; omit location to aggregate across all), or `GET ${API}/stock/levels[?location=&below=N]` for every item (a stock-on-hand report; `below=N` → the low-stock/reorder list). RESERVE stock for an order without shipping it: `POST ${API}/stock/reserve {item, location?, qty, ref?}` earmarks it (409 if it would oversell available), then `POST ${API}/stock/reservations/<id>/release` frees it or `POST ${API}/stock/reservations/<id>/fulfill` ships it (issues the qty + closes the reservation). Move between warehouses with `POST ${API}/stock/transfer {item, from, to, qty}` (guarded so you can't transfer more than the source holds). `GET ${API}/stock/moves` / `${API}/stock/reservations` list the history. Quantities are exact to 3 decimals (kg/litres OK). Use THIS for anything that must not oversell — the no-negative guarantee + reservations are the point — instead of a hand-maintained quantity field that races. INVENTORY VALUATION (what the stock on hand is WORTH — for a balance sheet / stock report): pass `unit_cost` on receipts, then `GET ${API}/stock/valuation[?item=&location=]` → each item+location's `{on_hand, avg_cost, value}` + a `total_value`, where avg_cost is the WEIGHTED-AVERAGE of the costed receipts (issues/transfers don't move it) and value = on_hand × avg_cost. An item received without any cost reads avg_cost/value null. LOT / BATCH / SERIAL + EXPIRY (track WHICH batch each quantity is — food/pharma expiry, recalls, serialized units): pass `lot` (and optional `expiry` date) on a `${API}/stock/moves` receipt; an issue that names a `lot` can't take more than that lot holds (409). `GET ${API}/stock/lots?item=&location=[&expiring_before=<date>]` → on-hand per lot with expiry, earliest-expiry-first (and an expiring-soon report). `GET ${API}/stock/allocate?item=&location=&qty=N` → a FEFO pick plan (which lots to pull, earliest expiry first) with any shortfall. A SERIAL number is just a lot with qty 1. Non-lot moves keep working unchanged. REORDER / REPLENISHMENT (auto-suggest what to buy when stock runs low): `POST ${API}/stock/reorder-rules {item, location?, reorder_point, reorder_qty?, target?, supplier?}` sets a per-item minimum; `GET ${API}/stock/reorder-rules` lists, `DELETE ${API}/stock/reorder-rules/<item>[?location=]` removes. `GET ${API}/stock/replenishment[?location=]` → every item whose AVAILABLE (on-hand − reservations) has dropped to/below its reorder_point, with a `suggested_order` (to `target` if set, else the fixed `reorder_qty`, else back up to the point) + supplier — a ready-to-order buy list. BILL OF MATERIALS (what a product is built from — for manufacturing/assembly/kits): ADMIN-only, `${API}/bom/*`. Define a recipe `POST ${API}/bom {product, notes?, lines:[{component, qty}]}` (SKU-like names; a component can itself be a built product → multi-level); `GET ${API}/bom` lists products with BOMs, `GET/DELETE ${API}/bom/<product>` fetch/remove one. The key call is EXPLODE: `GET ${API}/bom/<product>/explode?qty=N` recursively expands to the aggregated LEAF (raw) `components:[{component, qty}]` needed to build N (plus the `subassemblies` built along the way) — cycles are refused (409). Feed the exploded components into a stock issue to build the product. WORK ORDERS (actually build a product from its BOM — consumes components, produces finished goods): `POST ${API}/work-orders {product, qty, location?}` plans a build (needs a BOM); `GET ${API}/work-orders/<id>` shows the exploded `requirements` with availability + a `can_build` flag; `POST ${API}/work-orders/<id>/build` issues the leaf components from stock (all-or-nothing, 409 if short) and receives the finished product valued at the ROLLED-UP component cost (idempotent — re-build → 409); `POST ${API}/work-orders/<id>/cancel` cancels a planned one. MRP (what to buy to meet a production plan): `POST ${API}/mrp {demand:[{product, qty}], location?}` explodes the whole basket, nets the aggregated component needs against on-hand → `{requirements:[{component, required, available, shortfall}], shortfalls}` (a demanded product with no BOM is treated as a purchased item). " +
  "DOCUMENT FLOW (quotes → orders → invoices → payments for sales/procurement — line-item business documents with totals + tax + a paper trail, NOT flat rows): ADMIN-only, `${API}/documents/*`. Create `POST ${API}/documents {type, party?, date?, currency?, ref?, memo?, status?, lines:[{item?, description?, qty, unit_price, tax_rate?, dim?}]}` — `type` is any string ('quote','sales_order','invoice','purchase_order','bill','credit_note',…); each line's subtotal (qty×price), tax (tax_rate is a PERCENT 0–100), and total are computed SERVER-SIDE, summed into the document `{subtotal, tax, total}`; every doc gets an auto number per type (QUOTE-00001, INVOICE-00001, independent counters). The KILLER action is CONVERT: `POST ${API}/documents/<id>/convert {type, source_status?}` copies the lines into a NEW document of the target type and links it via `from_id` — so quote→order→invoice threads the whole deal (optionally stamp the source's status, e.g. quote→'accepted'). Move status with `POST ${API}/documents/<id>/status {status}` (your own flow: draft/sent/accepted/paid/…). Read `GET ${API}/documents/<id>` (header+lines) and `GET ${API}/documents[?type=&party=&status=&from_id=&from=&to=]` (list; `from_id` finds a doc's children). `PATCH ${API}/documents/<id>` edits the header anytime, but LINES can only be changed while status is 'draft' (a sent/paid doc is locked — 409); DELETE is draft-only too (cancel via status otherwise). Money exact to the cent. Use THIS for any quote/order/invoice/bill instead of a plain table so totals, tax, numbering, and the quote→invoice trail are handled for you. POST TO THE LEDGER (turn an invoice/bill into real double-entry accounting in one call): `POST ${API}/documents/<id>/post {total_account, base_account, tax_account?, total_side?}` builds a balanced journal entry from the doc's totals — for a SALE invoice `{total_account:'accounts_receivable', base_account:'revenue', tax_account:'tax_payable'}` posts Dr A/R (total), Cr Revenue (subtotal), Cr Tax (tax); for a PURCHASE bill add `total_side:'credit'` so it mirrors (Cr A/P, Dr Expense, Dr Tax). It's IDEMPOTENT — the doc records its `ledger_entry_id`, so a second post is refused (409 `posted`) — and it respects the period lock. Use this on invoice-confirm/payment so your books tie out automatically instead of hand-writing journal entries. POST TO STOCK (fulfil a document = move its line items in inventory): `POST ${API}/documents/<id>/post-stock {location?, direction?}` issues (sales) or receives (purchase) each line that names an `item` — a sales_order/invoice ISSUES (reduces on-hand), a purchase_order/bill RECEIVES (raises it, carrying the line's unit_price as cost so valuation works); direction is inferred from the doc type or forced with `direction:'issue'|'receive'`. It's IDEMPOTENT (the doc's `stock_posted` flag; re-post → 409) and ALL-OR-NOTHING for issues (availability is pre-checked across all lines, summing repeats of the same item, so a multi-line order never half-ships — 409 `stock` with the short item if any line can't be met). Use it on order-confirm/ship so inventory and the paperwork stay in lockstep. PAYMENTS / OUTSTANDING (record what's been paid against an invoice/bill; every doc reports `paid` + `outstanding`): `POST ${API}/documents/<id>/allocations {amount, ref?, memo?, date?}` applies a payment/credit (refused if it exceeds the outstanding unless `allowOverpay`), `GET …/allocations` lists them with paid/outstanding, `DELETE …/allocations/<allocId>` unapplies one. Set a doc's `due_date` (on create or PATCH) to drive aging. AR/AP AGING (a receivables/payables report — who owes what, how overdue): `GET ${API}/documents/aging?type=invoice[&as_of=&party=&buckets=30,60,90]` → open docs bucketed current/1-30/31-60/61-90/91+ by days past `due_date` (or doc_date), grouped `parties:[{party,total,aged}]` with `totals`. Fully-paid, draft, cancelled and void docs are excluded. Use `type=bill` for payables. TAX SUMMARY (a VAT/GST/sales-tax return — tax you collected vs tax you paid): `GET ${API}/documents/tax-summary?from=&to=[&sales_types=invoice&purchase_types=bill]` → `{output:{by_rate:[{rate,base,tax}], total_base, total_tax}, input:{…}, net_tax}` where output = tax on sales docs, input = tax on purchase docs, net_tax = what you owe (output − input). Broken down by rate; draft/cancelled/void excluded. " +
  "FILES: an `<input type=file accept=\"image/*,application/pdf\">`; read the file as a data URL and `POST /api/site/upload {slug, name, data}` (slug = `location.pathname.split('/')[2]`) → `{url}` is a PERMANENT link — ALWAYS save it into a row or it's orphaned. Images/PDF ≤6MB; never upload elsewhere. " +
  "SERVER FUNCTIONS + SECRETS (ONLY for server-side logic the endpoints above can't do: a 3rd-party API with a private key, a PAYMENT, or EMAIL — never hardcode a key). Declare `===FILE: isibi.functions.json===` = `{\"functions\":[{\"name\":\"<kebab>\",\"steps\":[…]}]}`. Each step is ONE of: " +
  "`{\"do\":\"fetch\",\"url\":\"https://…\",\"method\":\"POST\",\"headers\":{…},\"body\":{…},\"as\":\"r\"}` (→ `{{steps.r.status}}`/`{{steps.r.body}}`); `{\"do\":\"ai\",\"prompt\":\"…{{input.x}}…\",\"as\":\"r\"}` (→ `{{steps.r.text}}`); `{\"do\":\"email\",\"provider\":\"resend|sendgrid|postmark\",\"secret\":\"RESEND_KEY\",\"from\":\"you@d.com\",\"to\":\"{{input.email}}\",\"subject\":\"…\",\"html\":\"…\"}`; `{\"do\":\"checkout\",\"secret\":\"STRIPE_KEY\",\"amount\":2999,\"currency\":\"usd\",\"name\":\"…\",\"success_url\":\"…\",\"cancel_url\":\"…\",\"as\":\"s\"}` (cents; add `\"mode\":\"subscription\",\"interval\":\"month\"` for a sub); `{\"do\":\"save\",\"collection\":\"<declared table>\",\"data\":{…}}`; `{\"do\":\"read\",\"collection\":\"<declared table>\",\"limit\":20,\"as\":\"list\"}` (→ `{{steps.list.records}}`); `{\"do\":\"notify\",\"to\":\"{{input.owner_id}}\",\"type\":\"comment\",\"text\":\"Someone replied to your post\",\"link\":\"/post/{{input.post_id}}\"}` (drops an in-app notification into a MEMBER's inbox — `to` is a member id; use inside an on-insert trigger to notify on new comment/like/order); `{\"do\":\"respond\",\"data\":{…}}` (the JSON the browser gets). TEMPLATES: `{{input.x}}` · `{{steps.<as>.<path>}}` · `{{secret.NAME}}` (resolved server-side, injected ONLY into fetch/email/checkout, never sent to the browser). ≤8 steps, ≤2 fetch. " +
  "CALL a function: `POST /api/site/fn {slug, fn:'<name>', input:{…}}` → your respond data (payments: `location.href = d.url`). SECRETS: every `{{secret.NAME}}` (STRIPE_KEY, RESEND_KEY…) is added by the OWNER in Cloud → Secrets — tell them exactly which name(s) to add; never inline a key. EVENT TRIGGER: add `\"on\":{\"insert\":\"<table>\"}` OR `\"on\":{\"update\":\"<table>\"}` (sibling of steps) to run a function automatically after a row is inserted into / updated in that table (new order → email; a deal moved to `won` → log an activity or notify the rep), with the affected row's fields as `{{input.<field>}}` (updates also carry `{{input.id}}`); single-row writes only. Pair `on:{update}` with `transitions` for stage-driven automation (when the stage advances, do X). WEBHOOKS: a function with `\"on\":{\"insert\":\"<table>\"}` + a `fetch` step POSTing to an external URL = an outbound webhook on new rows (new order → notify Slack/Zapier/your server). SMS: a `fetch` step to a provider's REST API (e.g. Twilio) with the account secret. MAGIC-LINK / OTP: an `email` step that sends a code/link (store the code in a table via `save`, verify it in a second function) — same shape as the built-in password-reset. " +
  "Build REAL, working flows (a form that truly saves, a login that truly works, a dashboard of the visitor's own rows, a real checkout). Do NOT invent other backend endpoints — these are the only ones. ";

// Safety-net contract: the model wired the app to the backend API but forgot to
// emit isibi.schema.json (common enough that it can't be optional — a shipped app
// whose login/data silently 404s is a total failure). We ask for JUST the schema,
// inferred from the app's own code, and provision it before publishing.
export const SCHEMA_REPAIR_RULES =
  "A generated React app calls its per-site backend API but FORGOT to declare `isibi.schema.json`, so no database gets created and every `/auth` and `/rows` call fails on the live site. Given the project files, emit ONLY a single `===FILE: isibi.schema.json===` block whose body is the JSON schema — NO other files, NO prose, NO markdown fences. " +
  "Declare EVERY table the app reads or writes via `${API}/rows/<table>` (scan for each distinct `<table>`). Choose each table's access mode from how the code uses it: each logged-in user's OWN private rows (a dashboard, saved items, a personal to-do list) = `user`; a public shared list everyone reads but only a logged-in visitor posts to (board / comments / reviews) = `feed`; a submit-only form only the owner reads (contact / waitlist / orders) = `collect`; owner-managed public content everyone reads (products / menu / posts) = `display`, OR `admin` if the app has an in-app admin screen that creates/edits that content (checks `user.role === 'admin'`). If the app has login (`/auth/signup` or `/auth/login`), its per-user data tables are `user` (or `feed` for shared-but-authored lists). " +
  "Infer each table's columns from the JSON the app POSTs and the fields it renders. NEVER declare `id`, `created_at`, or `owner_id` (the platform adds those). Body format EXACTLY: `{\"tables\":[{\"name\":\"<snake>\",\"access\":\"collect|display|user|feed|admin\",\"columns\":[{\"name\":\"<snake>\",\"type\":\"text|integer|real|boolean|json\"}]}]}`. Output ONLY the isibi.schema.json file block.";

// Auto-fix contract — used when the generated app calls the backend API but wires
// the URL WITHOUT the site slug, so every request 404s on the live site (the app
// compiles fine, so the build loop never catches it — this is a RUNTIME wiring bug).
// The one true base is `/api/db/<slug>/…` where `<slug> = location.pathname.split('/')[2]`;
// the model must re-point EVERY backend call through it.
export const WIRING_REPAIR_RULES =
  "You are a senior React engineer fixing a SHIPPED-BUT-BROKEN backend wiring bug. The app calls its per-site backend API, but the URLs are MISSING the site slug, so every `/auth` and `/rows` request 404s on the live site (the app compiles, so this was never caught). " +
  "THE ONE TRUE BASE: `const API = '/api/db/' + (location.pathname.split('/')[2] || '')` — the site is served at `/s/<slug>/`, so `location.pathname.split('/')[2]` IS the slug. EVERY backend call MUST go through it: `${API}/auth/signup`, `${API}/auth/login`, `${API}/auth/me`, `${API}/rows/<table>`, `${API}/rows/<table>/<id>`, `${API}/rows/<table>/stats`, `${API}/rows/<table>/changes`, plus any `?where=`/`?q=`/`?expand=`/`?children=`/`?sort=` query on `${API}/rows/<table>`. " +
  "Find EVERY fetch/axios call in the project that hits `/api/db…` and rewrite it to include the slug via that `API` base. Fix malformed URLs too (e.g. a query string with no `/rows/<table>?` prefix). Define `API` ONCE (a helper/hook/module) and use it everywhere — do NOT hardcode `/api/db/auth` or `/api/db/rows` or `` `/api/db${x}` `` without the slug. Preserve auth headers (`Authorization: Bearer <token>`), methods, and bodies exactly. " +
  "Return ONLY the CORRECTED file blocks in the SAME format — a line `===FILE: <relative/path>===` on its own line, then the file's raw contents IN FULL (not a diff). Return only the files you change. Change NOTHING about the design, layout, or copy — this is a URL-wiring fix only. Import ONLY from " + REACT_DEPS.join(", ") + ". If (and only if) every backend call already includes the slug, return NO file blocks at all. Output ONLY file blocks — NO prose, NO markdown fences.";

// System contract for emitting the project. Kept focused for the POC: structure,
// deps, Tailwind, routing, real content, no dead interactions.
export const REACT_RULES =
  "You are a world-class product designer + senior React engineer. Output a COMPLETE, COMPILABLE Vite + React + Tailwind project as a series of files. " +
  "OUTPUT FORMAT (STRICT): for every file, write a line `===FILE: <relative/path>===` on its OWN line, then the file's raw contents, then the next `===FILE:` marker. NO markdown fences, NO prose, NO commentary before/after — the response is ONLY file blocks. " +
  "REQUIRED FILES: `index.html` (has <div id=\"root\"></div> + <script type=\"module\" src=\"/src/main.jsx\">, a real <title> + <meta name=description>), `src/main.jsx` (mounts <App/> inside <HashRouter>), `src/App.jsx` (declares <Routes> for every page), `src/index.css` (exactly `@tailwind base;@tailwind components;@tailwind utilities;` plus any @layer additions), one file per page under `src/pages/`, and shared pieces under `src/components/`. You MAY also emit `tailwind.config.js` to extend the theme (colors/fonts). Do NOT emit package.json, vite.config.js, or node_modules. " +
  "ROUTING: use `HashRouter` (NOT BrowserRouter) from react-router-dom — the published site is served from a sub-path on static hosting, and HashRouter routes via the URL hash so every route works with no server rewrites. Internal links are still `<Link to=\"/gallery\">` (the # is handled for you). " +
  "DEPENDENCIES: import ONLY from these installed packages — " + REACT_DEPS.join(", ") + ". Use `react-router-dom` (HashRouter, Link, Routes, Route, useParams, useLocation) for navigation. Use `lucide-react` for icons. NO other npm packages, NO CDN <script> tags, NO external CSS/UI libraries. " +
  "STYLING: Tailwind utility classes via className ONLY. Load real Google Fonts with a <link> in index.html and wire them through tailwind.config.js fontFamily. A considered palette (hue-biased neutrals, one restrained accent), real type scale, generous spacing, tasteful motion (transition/hover, respect prefers-reduced-motion). Award-winning, editorial — never a generic template. " +
  "ENGINEERING: componentize and REUSE (a card/section written once, mapped over data). Real, specific copy — never lorem, never 'Welcome to X'. Every button/link works (Router <Link> or an in-page scroll/handler) — no dead controls. Semantic, accessible (focus states, alt text, aria), responsive to 360px. Guard any risky JS in try/catch. " +
  "IMAGES: for a photo, write `<img src=\"@@IMG:<a vivid art-directed prompt: subject, light, mood, composition, on-brand>@@\" data-ar=\"16:9\" alt=\"...\" className=\"...\"/>` — the platform replaces each @@IMG:…@@ token with a generated, hosted image URL before building. Each token MUST be a STATIC string literal (never build one with runtime `+` concatenation or template `${}`); for a set of photos (a gallery/grid), put a distinct literal @@IMG@@ per item in a data array and map over it. Size via className (object-cover). EVERY image depicts THIS site's real subject. Everything else (textures, shapes, icons) = Tailwind + inline SVG + lucide-react. " +
  BACKEND_RULES;

